window.C3KO_DATA = {"version":1,"levels":[{"id":"A1","name":["Beginner","Pemula"],"goal":["Introduce yourself, talk about daily life, ask simple questions.","Memperkenalkan diri, membicarakan kehidupan sehari-hari, bertanya hal sederhana."],"topics":[{"id":"a1-be","title":["Verb to be: am, is, are","Kata kerja to be: am, is, are"],"what":["'Be' links the subject to a description, a place, a job or an age. English sentences always need a verb, so 'be' is needed even where many languages use no verb at all.","'Be' menghubungkan subjek dengan keterangan, tempat, pekerjaan atau umur. Kalimat bahasa Inggris selalu butuh kata kerja, jadi 'be' dipakai di tempat yang dalam bahasa Indonesia sering tanpa kata kerja."],"pattern":[{"head":[["Subject","Subjek"],["Positive","Positif"],["Negative","Negatif"],["Question","Pertanyaan"]],"rows":[["I","I {am} / I'm","I am not / I'm not","{Am} I…?"],["he / she / it","{is} / 's","{isn't}","{Is} he…?"],["you / we / they","{are} / 're","{aren't}","{Are} you…?"]]}],"examples":[["I'm a nurse.","Saya perawat."],["She isn't at home.","Dia tidak di rumah."],["Are they your friends?","Apakah mereka temanmu?"],["I'm 30 (years old).","Umur saya 30 tahun."]],"tip":["Never leave out 'be': say 'She is tired', not 'She tired'. For age, use 'be', not 'have': 'I am 30.'","Jangan menghilangkan 'be': katakan 'She is tired', bukan 'She tired'. Untuk umur pakai 'be', bukan 'have': 'I am 30.'"]},{"id":"a1-pronouns","title":["Subject and object pronouns","Kata ganti subjek dan objek"],"what":["Subject pronouns come before the verb; object pronouns come after a verb or a preposition. English pronouns show gender only in he/she (him/her).","Kata ganti subjek ada sebelum kata kerja; kata ganti objek ada setelah kata kerja atau kata depan. Kata ganti bahasa Inggris hanya membedakan gender pada he/she (him/her)."],"pattern":[{"head":[["Subject","Subjek"],["Object","Objek"],["Meaning","Arti"]],"rows":[["I","{me}",["I / me","saya"]],["you","{you}",["you","kamu / Anda / kalian"]],["he","{him}",["he (man)","dia (laki-laki)"]],["she","{her}",["she (woman)","dia (perempuan)"]],["it","{it}",["it (thing, animal)","ia / itu (benda, hewan)"]],["we","{us}",["we","kami / kita"]],["they","{them}",["they","mereka"]]]}],"examples":[["She likes him.","Dia (pr.) menyukainya (lk.)."],["Call me tomorrow.","Telepon saya besok."],["This is for them.","Ini untuk mereka."]],"tip":["Many languages have one word for 'he' and 'she'; English makes you choose. Use 'it' for things and animals, and 'they' for one person of unknown gender.","'Dia' bisa 'he' atau 'she' dalam bahasa Inggris: kamu harus memilih. Pakai 'it' untuk benda dan hewan, dan 'they' untuk satu orang yang gendernya tidak diketahui."]},{"id":"a1-articles","title":["Articles: a, an, the","Artikel: a, an, the"],"what":["'A/an' means one of many, mentioned for the first time. 'The' means a specific one the listener knows. Plural and uncountable nouns in general take no article.","'A/an' berarti salah satu, disebut pertama kali. 'The' berarti yang tertentu, yang sudah diketahui pendengar. Kata benda jamak dan tak terhitung secara umum tanpa artikel."],"pattern":[{"head":[["Article","Artikel"],["Use","Penggunaan"],["Example","Contoh"]],"rows":[["{a}",["before a consonant sound","sebelum bunyi konsonan"],"a book, a university"],["{an}",["before a vowel sound","sebelum bunyi vokal"],"an apple, an hour"],["{the}",["a specific / known thing","benda tertentu / sudah diketahui"],"the book on the table"],["—",["plural or uncountable, in general","jamak atau tak terhitung, secara umum"],"I like dogs. Water is life."]]}],"examples":[["I have a car. The car is red.","Saya punya mobil. Mobil itu merah."],["She is an engineer.","Dia seorang insinyur."],["The sun is hot.","Matahari panas."]],"tip":["Jobs need 'a/an': 'He is a teacher', not 'He is teacher'. 'An hour' (h is silent) but 'a university' (sounds like 'you').","Pekerjaan butuh 'a/an': 'He is a teacher', bukan 'He is teacher'. 'An hour' (h tidak dibaca) tetapi 'a university' (bunyinya 'you')."]},{"id":"a1-plurals","title":["Plural nouns","Kata benda jamak"],"what":["Most nouns add -s. Some spelling rules apply, and a few common nouns are irregular. Many languages repeat the word or add nothing; English adds an ending.","Sebagian besar kata benda ditambah -s. Ada beberapa aturan ejaan, dan beberapa kata benda umum tidak beraturan. Bahasa Indonesia mengulang kata (buku-buku); bahasa Inggris menambah akhiran."],"pattern":[{"head":[["Rule","Aturan"],["Singular","Tunggal"],["Plural","Jamak"]],"rows":[[["most nouns: + s","sebagian besar: + s"],"book, car","book{s}, car{s}"],[["-s, -sh, -ch, -x: + es","-s, -sh, -ch, -x: + es"],"bus, dish, watch","bus{es}, dish{es}, watch{es}"],[["consonant + y → ies","konsonan + y → ies"],"city, baby","cit{ies}, bab{ies}"],[["-f / -fe → ves","-f / -fe → ves"],"knife, wife","kni{ves}, wi{ves}"],[["irregular","tidak beraturan"],"man, woman, child, person, foot, tooth","{men}, {women}, {children}, {people}, {feet}, {teeth}"]]}],"examples":[["I have two children.","Saya punya dua anak."],["There are three buses.","Ada tiga bus."],["Many people live here.","Banyak orang tinggal di sini."]],"tip":["After a number, always use the plural: 'two books', not 'two book'. Some nouns are the same: sheep, fish.","Setelah angka selalu pakai jamak: 'two books', bukan 'two book'. Beberapa kata sama saja: sheep, fish."]},{"id":"a1-this-that","title":["This, that, these, those","This, that, these, those"],"what":["Demonstratives point at things. 'This/these' are near the speaker; 'that/those' are farther away. They agree with singular or plural.","Kata tunjuk menunjuk benda. 'This/these' dekat dengan pembicara; 'that/those' lebih jauh. Bentuknya menyesuaikan tunggal atau jamak."],"pattern":[{"head":["",["Near","Dekat"],["Far","Jauh"]],"rows":[[["Singular","Tunggal"],"{this} book","{that} book"],[["Plural","Jamak"],"{these} books","{those} books"]]}],"examples":[["This is my phone.","Ini ponsel saya."],["Are those your keys?","Apakah itu kuncimu?"],["I like these shoes.","Saya suka sepatu ini."]],"tip":["Choose by distance and by number: this/that for one, these/those for more.","'Ini' = this/these, 'itu' = that/those: perhatikan tunggal atau jamak."]},{"id":"a1-possessives","title":["Possessives: my, your, 's","Kepemilikan: my, your, 's"],"what":["Possessive adjectives go before a noun. For people and names, add 's. The owner comes first: Anna's bag.","Kata sifat kepemilikan diletakkan sebelum kata benda. Untuk orang dan nama, tambahkan 's. Pemilik di depan, kebalikan urutan bahasa Indonesia."],"pattern":[{"head":[["Pronoun","Kata ganti"],["Possessive","Kepemilikan"],["Example","Contoh"]],"rows":[["I","{my}","my car"],["you","{your}","your car"],["he","{his}","his car"],["she","{her}","her car"],["it","{its}","its name"],["we","{our}","our car"],["they","{their}","their car"]]},{"title":["Names and nouns","Nama dan kata benda"],"head":[["Owner","Pemilik"],["Form","Bentuk"],["Meaning","Arti"]],"rows":[["Anna","Anna{'s} bag",["Anna's bag","tas Anna"]],["my parents","my parents{'} house",["my parents' house","rumah orang tua saya"]],["the children","the children{'s} toys",["the children's toys","mainan anak-anak"]]]}],"examples":[["This is my brother's car.","Ini mobil saudara laki-laki saya."],["Their house is big.","Rumah mereka besar."],["What's your name?","Siapa namamu?"]],"tip":["'Its' (possessive) has no apostrophe; 'it's' means 'it is'.","'Its' (kepemilikan) tanpa apostrof; 'it's' berarti 'it is'."]},{"id":"a1-have","title":["Have / has (got)","Have / has (got)"],"what":["'Have' shows possession, family, illness and some fixed expressions. 'He/she/it' takes 'has'. British English also uses 'have got'.","'Have' menyatakan kepemilikan, keluarga, sakit dan beberapa ungkapan tetap. 'He/she/it' memakai 'has'. Bahasa Inggris Britania juga memakai 'have got'."],"pattern":[{"head":[["Subject","Subjek"],["Positive","Positif"],["Negative","Negatif"],["Question","Pertanyaan"]],"rows":[["I / you / we / they","{have}","{don't have}","{Do} you {have}…?"],["he / she / it","{has}","{doesn't have}","{Does} she {have}…?"],[["British: have got","Britania: have got"],"I've got / she's got","I haven't got","Have you got…?"]]}],"examples":[["I have two sisters.","Saya punya dua saudara perempuan."],["She has a headache.","Dia sakit kepala."],["Do you have a pen?","Kamu punya pulpen?"]],"tip":["After 'doesn't', use 'have', not 'has': 'He doesn't have a car.'","Setelah 'doesn't', pakai 'have', bukan 'has': 'He doesn't have a car.'"]},{"id":"a1-present-simple","title":["Present simple: positive","Present simple: positif"],"what":["For habits, routines, facts and permanent situations. Add -s for he/she/it.","Untuk kebiasaan, rutinitas, fakta dan keadaan tetap. Tambahkan -s untuk he/she/it."],"pattern":[{"head":[["Subject","Subjek"],["Verb","Kata kerja"],["Example","Contoh"]],"rows":[["I / you / we / they",["base form","bentuk dasar"],"I work, they live"],["he / she / it","+ {s}","she work{s}, he live{s}"],[["-s, -sh, -ch, -x, -o: + es","-s, -sh, -ch, -x, -o: + es"],"+ {es}","watch{es}, go{es}, do{es}"],[["consonant + y → ies","konsonan + y → ies"],"+ {ies}","stud{ies}, tr{ies}"],[["irregular","tidak beraturan"],"","have → {has}"]]}],"examples":[["I get up at seven.","Saya bangun jam tujuh."],["He works in a bank.","Dia bekerja di bank."],["Water boils at 100 °C.","Air mendidih pada 100 °C."]],"tip":["The -s is easy to forget in speech: 'She speak English' is wrong, 'She speaks English' is right.","Akhiran -s sering terlupa saat berbicara: 'She speak English' salah, 'She speaks English' benar."]},{"id":"a1-do-does","title":["Present simple: questions and negatives (do / does)","Present simple: pertanyaan dan negatif (do / does)"],"what":["Questions and negatives need the helper 'do/does'. The main verb goes back to the base form, because 'does' already carries the -s.","Pertanyaan dan kalimat negatif butuh kata bantu 'do/does'. Kata kerja utama kembali ke bentuk dasar, karena 'does' sudah membawa -s."],"pattern":[{"head":["","I / you / we / they","he / she / it"],"rows":[[["Negative","Negatif"],"I {don't} work","she {doesn't} work"],[["Question","Pertanyaan"],"{Do} you work?","{Does} she work?"],[["Short answer","Jawaban singkat"],"Yes, I do. / No, I don't.","Yes, she does. / No, she doesn't."],[["With a question word","Dengan kata tanya"],"Where {do} you live?","What {does} he do?"]]}],"examples":[["I don't eat meat.","Saya tidak makan daging."],["Does he speak Indonesian?","Apakah dia bisa bahasa Indonesia?"],["What do you do?","Apa pekerjaanmu?"]],"tip":["Never double the -s: 'Does she like…?' not 'Does she likes…?'","Jangan menggandakan -s: 'Does she like…?' bukan 'Does she likes…?'"]},{"id":"a1-present-continuous","title":["Present continuous","Present continuous"],"what":["'Be' + verb-ing for actions happening now or around now, and temporary situations.","'Be' + kata kerja-ing untuk tindakan yang sedang terjadi sekarang atau sekitar sekarang, dan keadaan sementara."],"pattern":[{"head":[["Subject","Subjek"],["Form","Bentuk"],["Example","Contoh"]],"rows":[["I","{am} + -ing","I'm cooking."],["he / she / it","{is} + -ing","She's reading."],["you / we / they","{are} + -ing","They're playing."]]},{"title":["Spelling of -ing","Ejaan -ing"],"head":[["Rule","Aturan"],["Example","Contoh"]],"rows":[[["most verbs: + ing","sebagian besar: + ing"],"work → work{ing}"],[["-e: drop e","-e: e dihapus"],"make → mak{ing}"],[["short vowel + consonant: double","vokal pendek + konsonan: digandakan"],"run → ru{nning}, sit → si{tting}"],[["-ie → -ying","-ie → -ying"],"lie → l{ying}"]]}],"examples":[["I'm working now.","Saya sedang bekerja sekarang."],["What are you doing?","Kamu sedang apa?"],["She isn't listening.","Dia tidak sedang mendengarkan."]],"tip":["Some verbs are rarely used in -ing: like, want, know, need, understand. Say 'I know', not 'I am knowing'.","Beberapa kata kerja jarang dipakai dengan -ing: like, want, know, need, understand. Katakan 'I know', bukan 'I am knowing'."]},{"id":"a1-there-is","title":["There is / there are","There is / there are"],"what":["To say that something exists or is in a place. 'There is' for one thing or uncountables, 'there are' for plurals.","Untuk menyatakan sesuatu ada atau berada di suatu tempat ('ada'). 'There is' untuk satu benda atau tak terhitung, 'there are' untuk jamak."],"pattern":[{"head":["",["Singular / uncountable","Tunggal / tak terhitung"],["Plural","Jamak"]],"rows":[[["Positive","Positif"],"{There is} a bank.","{There are} two banks."],[["Negative","Negatif"],"{There isn't} any milk.","{There aren't} any shops."],[["Question","Pertanyaan"],"{Is there} a lift?","{Are there} any chairs?"]]}],"examples":[["There's a supermarket near here.","Ada supermarket di dekat sini."],["Are there any questions?","Ada pertanyaan?"],["There isn't time.","Tidak ada waktu."]],"tip":["Don't use 'have' to say something exists: 'There is a problem', not 'It has a problem'.","Jangan pakai 'have' untuk 'ada': 'There is a problem', bukan 'It has a problem'."]},{"id":"a1-can","title":["Can / can't","Can / can't"],"what":["'Can' expresses ability, permission and requests. It never changes and is followed by the base form without 'to'.","'Can' menyatakan kemampuan, izin dan permintaan. Bentuknya tidak pernah berubah dan diikuti bentuk dasar tanpa 'to'."],"pattern":[{"head":[["Form","Bentuk"],["Example","Contoh"]],"rows":[[["Positive","Positif"],"She {can} swim."],[["Negative","Negatif"],"I {can't} (cannot) drive."],[["Question","Pertanyaan"],"{Can} you help me?"],[["Short answer","Jawaban singkat"],"Yes, I can. / No, I can't."]]}],"examples":[["Can I pay by card?","Bisa saya bayar pakai kartu?"],["He can't speak French.","Dia tidak bisa bahasa Prancis."],["Can you open the window, please?","Bisa tolong buka jendelanya?"]],"tip":["No -s and no 'to': 'She can swim', not 'She cans swim' or 'She can to swim'.","Tanpa -s dan tanpa 'to': 'She can swim', bukan 'She cans swim' atau 'She can to swim'."]},{"id":"a1-imperative","title":["Imperative","Kalimat perintah"],"what":["Instructions and requests use the base form without a subject. 'Don't' makes it negative; 'let's' includes the speaker.","Instruksi dan permintaan memakai bentuk dasar tanpa subjek. 'Don't' membuatnya negatif; 'let's' mengajak termasuk pembicara."],"pattern":[{"head":[["Type","Jenis"],["Form","Bentuk"],["Example","Contoh"]],"rows":[[["Positive","Positif"],["base form","bentuk dasar"],"{Open} the door."],[["Negative","Negatif"],"don't + base","{Don't} touch it."],[["Suggestion","Ajakan"],"let's + base","{Let's} go."],[["Polite","Sopan"],"please + …","Sit down, please."]]}],"examples":[["Turn left at the bank.","Belok kiri di bank."],["Don't be late.","Jangan terlambat."],["Let's have lunch.","Ayo makan siang."]],"tip":["Add 'please' or use 'Can you…?' to sound polite; a bare imperative can sound bossy.","Tambahkan 'please' atau pakai 'Can you…?' agar sopan; perintah langsung bisa terdengar memerintah."]},{"id":"a1-prep-place","title":["Prepositions of place: in, on, at, under…","Kata depan tempat: in, on, at, under…"],"what":["'In' = inside an area or space, 'on' = on a surface, 'at' = at a point or place where something happens. Many languages use one word for all three.","'In' = di dalam area atau ruang, 'on' = di atas permukaan, 'at' = di suatu titik atau tempat kegiatan. 'Di' dalam bahasa Indonesia mencakup ketiganya."],"pattern":[{"head":[["Preposition","Kata depan"],["Use","Penggunaan"],["Example","Contoh"]],"rows":[["{in}",["inside; cities, countries","di dalam; kota, negara"],"in the box, in Jakarta"],["{on}",["on a surface; floors, streets (US)","di permukaan; lantai, jalan"],"on the table, on the second floor"],["{at}",["a point; home, work, school, events","titik; rumah, kantor, sekolah, acara"],"at the door, at home, at a party"],["{under} / {next to} / {between} / {behind} / {in front of}",["position","posisi"],"under the bed, next to the bank"]]}],"examples":[["The keys are on the table.","Kuncinya di atas meja."],["I'm at work.","Saya di kantor."],["She lives in Bandung.","Dia tinggal di Bandung."]],"tip":["Fixed: at home, at work, at school, in bed, in hospital, on the bus.","Tetap: at home, at work, at school, in bed, in hospital, on the bus."]},{"id":"a1-prep-time","title":["Prepositions of time: in, on, at","Kata depan waktu: in, on, at"],"what":["'At' for clock times and points, 'on' for days and dates, 'in' for months, years, seasons and parts of the day.","'At' untuk jam dan titik waktu, 'on' untuk hari dan tanggal, 'in' untuk bulan, tahun, musim dan bagian hari."],"pattern":[{"head":[["Preposition","Kata depan"],["Use","Penggunaan"],["Example","Contoh"]],"rows":[["{at}",["clock times, night, weekend (UK)","jam, malam, akhir pekan (UK)"],"at 7 o'clock, at night"],["{on}",["days, dates","hari, tanggal"],"on Monday, on 17 August"],["{in}",["months, years, seasons, the morning","bulan, tahun, musim, pagi hari"],"in May, in 2026, in the morning"],["—",["with this/next/last/every","dengan this/next/last/every"],"next week, every day"]]}],"examples":[["The class starts at nine.","Kelasnya mulai jam sembilan."],["I was born in 1990.","Saya lahir tahun 1990."],["See you on Friday.","Sampai jumpa hari Jumat."]],"tip":["No preposition before next/last/this/every: 'next Monday', not 'on next Monday'.","Tanpa kata depan sebelum next/last/this/every: 'next Monday', bukan 'on next Monday'."]},{"id":"a1-questions","title":["Question words","Kata tanya"],"what":["Question word + auxiliary (do/does/is/are/can) + subject + verb. The auxiliary comes before the subject.","Kata tanya + kata bantu (do/does/is/are/can) + subjek + kata kerja. Kata bantu ada sebelum subjek."],"pattern":[{"head":[["Word","Kata"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{what}",["what","apa"],"What do you want?"],["{who}",["who","siapa"],"Who is she?"],["{where}",["where","di mana / ke mana"],"Where do you live?"],["{when}",["when","kapan"],"When is the meeting?"],["{why}",["why","mengapa"],"Why are you late?"],["{how}",["how","bagaimana"],"How are you?"],["{how much / many}",["how much / many","berapa"],"How much is it?"],["{which}",["which","yang mana"],"Which bus goes to the airport?"],["{whose}",["whose","milik siapa"],"Whose bag is this?"]]}],"examples":[["Where are you from?","Kamu dari mana?"],["How old is your son?","Berapa umur anakmu?"],["What time is it?","Jam berapa sekarang?"]],"tip":["Keep the auxiliary: 'Where do you live?', not 'Where you live?'","Jangan lupa kata bantu: 'Where do you live?', bukan 'Where you live?'"]},{"id":"a1-numbers-time","title":["Numbers, prices, dates and time","Angka, harga, tanggal dan jam"],"what":["Cardinal numbers count, ordinal numbers (first, second…) give order and dates. Time is said with 'past' and 'to' or with digits.","Bilangan pokok untuk menghitung, bilangan urutan (first, second…) untuk urutan dan tanggal. Jam disebut dengan 'past' dan 'to' atau dengan angka."],"pattern":[{"title":["Ordinals","Bilangan urutan"],"head":[["Number","Angka"],["Ordinal","Urutan"],["Number","Angka"],["Ordinal","Urutan"]],"rows":[["1","{first} (1st)","4","fourth (4th)"],["2","{second} (2nd)","5","{fifth} (5th)"],["3","{third} (3rd)","20","{twentieth} (20th)"]]},{"title":["Telling time","Menyebut jam"],"head":[["Time","Jam"],["Words","Kata"],["Digits","Angka"]],"rows":[["7:00","seven {o'clock}","seven"],["7:15","(a) quarter {past} seven","seven fifteen"],["7:30","half {past} seven","seven thirty"],["7:45","(a) quarter {to} eight","seven forty-five"]]}],"examples":[["It costs twenty-five euros.","Harganya dua puluh lima euro."],["My birthday is on the third of May.","Ulang tahun saya tanggal tiga Mei."],["It's half past six.","Sekarang setengah tujuh."]],"tip":["'Half past six' = 6:30: English counts from the past hour. (Some languages count towards the next hour.)","'Half past six' = 6.30. 'Setengah tujuh' dihitung menuju jam berikutnya; bahasa Inggris dihitung dari jam sebelumnya."]}]},{"id":"A2","name":["Elementary","Dasar"],"goal":["Talk about the past, plans and predictions; compare things; describe how often and how.","Bercerita tentang masa lalu, rencana dan perkiraan; membandingkan; menjelaskan seberapa sering dan bagaimana."],"topics":[{"id":"a2-past-simple","title":["Past simple: regular verbs","Past simple: kata kerja beraturan"],"what":["For finished actions at a finished time in the past (yesterday, last year, in 2020). Regular verbs add -ed. Questions and negatives use 'did' + base form.","Untuk tindakan yang selesai pada waktu lampau yang sudah selesai (yesterday, last year, in 2020). Kata kerja beraturan ditambah -ed. Pertanyaan dan negatif memakai 'did' + bentuk dasar."],"pattern":[{"head":[["Form","Bentuk"],["Example","Contoh"]],"rows":[[["Positive","Positif"],"I work{ed} yesterday."],[["Negative","Negatif"],"I {didn't} work."],[["Question","Pertanyaan"],"{Did} you work?"]]},{"title":["Spelling of -ed","Ejaan -ed"],"head":[["Rule","Aturan"],["Example","Contoh"]],"rows":[[["+ ed","+ ed"],"play → play{ed}"],[["-e: + d","-e: + d"],"live → live{d}"],[["consonant + y → ied","konsonan + y → ied"],"study → stud{ied}"],[["short vowel + consonant: double","vokal pendek + konsonan: digandakan"],"stop → sto{pped}"]]}],"examples":[["We watched a film last night.","Kami menonton film tadi malam."],["Did you call her?","Apakah kamu meneleponnya?"],["She didn't like the food.","Dia tidak suka makanannya."]],"tip":["After 'did/didn't' use the base form: 'Did you watch?', not 'Did you watched?'","Setelah 'did/didn't' pakai bentuk dasar: 'Did you watch?', bukan 'Did you watched?'"]},{"id":"a2-past-irregular","title":["Past simple: irregular verbs and was/were","Past simple: kata kerja tidak beraturan dan was/were"],"what":["Many common verbs have their own past form, which must be learned. 'Be' has two past forms: was and were.","Banyak kata kerja umum punya bentuk lampau sendiri yang harus dihafal. 'Be' punya dua bentuk lampau: was dan were."],"pattern":[{"head":[["Base","Dasar"],["Past","Lampau"],["Base","Dasar"],["Past","Lampau"]],"rows":[["go","{went}","buy","{bought}"],["have","{had}","see","{saw}"],["make","{made}","take","{took}"],["eat","{ate}","get","{got}"],["come","{came}","say","{said}"]]},{"title":["Be","Be"],"head":[["Subject","Subjek"],["Positive","Positif"],["Negative","Negatif"]],"rows":[["I / he / she / it","{was}","{wasn't}"],["you / we / they","{were}","{weren't}"]]}],"examples":[["I went to Bali last year.","Saya pergi ke Bali tahun lalu."],["Where were you yesterday?","Kamu di mana kemarin?"],["He didn't go to work.","Dia tidak pergi bekerja."]],"tip":["Irregular verbs are only irregular in the positive: 'He went', but 'He didn't go' and 'Did he go?'","Kata kerja tidak beraturan hanya berubah di kalimat positif: 'He went', tetapi 'He didn't go' dan 'Did he go?'"]},{"id":"a2-past-continuous","title":["Past continuous","Past continuous"],"what":["was/were + -ing for an action in progress at a past moment, often interrupted by a shorter past simple action.","was/were + -ing untuk tindakan yang sedang berlangsung pada suatu saat di masa lalu, sering disela tindakan past simple yang lebih singkat."],"pattern":[{"head":[["Use","Penggunaan"],["Example","Contoh"]],"rows":[[["in progress at a time","sedang berlangsung pada suatu waktu"],"At 8 pm I {was cooking}."],[["interrupted (when)","disela (when)"],"I {was cooking} when the phone {rang}."],[["two at the same time (while)","dua bersamaan (while)"],"While she {was reading}, he {was sleeping}."]]}],"examples":[["What were you doing at ten?","Kamu sedang apa jam sepuluh?"],["It was raining when we left.","Sedang hujan ketika kami berangkat."],["They weren't listening.","Mereka tidak sedang mendengarkan."]],"tip":["Long background action = past continuous; short event = past simple.","Tindakan latar yang panjang = past continuous; peristiwa singkat = past simple."]},{"id":"a2-going-to","title":["Going to: plans and predictions","Going to: rencana dan perkiraan"],"what":["be + going to + base form for plans already decided, and for predictions based on what you can see now.","be + going to + bentuk dasar untuk rencana yang sudah diputuskan, dan untuk perkiraan berdasarkan apa yang terlihat sekarang."],"pattern":[{"head":[["Use","Penggunaan"],["Example","Contoh"]],"rows":[[["plan / intention","rencana / niat"],"I'{m going to} study medicine."],[["evidence now","bukti sekarang"],"Look at those clouds. It'{s going to} rain."],[["negative / question","negatif / pertanyaan"],"She {isn't going to} come. {Are} you {going to} buy it?"]]}],"examples":[["We're going to visit my parents.","Kami akan mengunjungi orang tua saya."],["What are you going to do?","Apa yang akan kamu lakukan?"],["Be careful, you're going to fall!","Hati-hati, kamu bisa jatuh!"]],"tip":["Don't forget 'be': 'I'm going to…', not 'I going to…'.","Jangan lupa 'be': 'I'm going to…', bukan 'I going to…'."]},{"id":"a2-will","title":["Will: decisions, offers, predictions","Will: keputusan, tawaran, perkiraan"],"what":["will + base form for decisions made at the moment of speaking, offers, promises and opinions about the future.","will + bentuk dasar untuk keputusan saat berbicara, tawaran, janji dan pendapat tentang masa depan."],"pattern":[{"head":[["Use","Penggunaan"],["Example","Contoh"]],"rows":[[["instant decision","keputusan seketika"],"I'm thirsty. I'{ll} have water."],[["offer / promise","tawaran / janji"],"I'{ll} help you. I {won't} tell anyone."],[["opinion / prediction","pendapat / perkiraan"],"I think it {will} be easy."],[["question","pertanyaan"],"{Will} you marry me?"]]}],"examples":[["I'll call you tonight.","Saya akan meneleponmu nanti malam."],["Don't worry, it won't hurt.","Jangan khawatir, tidak akan sakit."],["Who do you think will win?","Menurutmu siapa yang akan menang?"]],"tip":["Plan made before → going to. Decision now → will: 'The phone's ringing. I'll answer it.'","Rencana sebelumnya → going to. Keputusan sekarang → will: 'The phone's ringing. I'll answer it.'"]},{"id":"a2-present-perfect","title":["Present perfect: experience (ever, never)","Present perfect: pengalaman (ever, never)"],"what":["have/has + past participle for life experience and past actions with a result now, when the time is not said.","have/has + partisip lampau untuk pengalaman hidup dan tindakan lampau yang hasilnya terasa sekarang, tanpa menyebut waktunya."],"pattern":[{"head":[["Form","Bentuk"],["Example","Contoh"]],"rows":[[["Positive","Positif"],"I {have been} to Japan."],[["he / she / it","he / she / it"],"She {has seen} that film."],[["Negative","Negatif"],"I {haven't eaten} sushi. / I've {never} eaten sushi."],[["Question","Pertanyaan"],"{Have} you {ever} {been} to Prague?"]]}],"examples":[["Have you ever been to Europe?","Pernah ke Eropa?"],["I've lost my keys.","Kunci saya hilang."],["He has never driven a car.","Dia belum pernah menyetir mobil."]],"tip":["No finished time with present perfect: 'I've seen it', but 'I saw it yesterday'.","Jangan pakai waktu yang sudah selesai dengan present perfect: 'I've seen it', tetapi 'I saw it yesterday'."]},{"id":"a2-comparison","title":["Comparatives and superlatives","Komparatif dan superlatif"],"what":["Short adjectives add -er/-est; long ones use more/most. 'Than' introduces the second thing compared.","Kata sifat pendek ditambah -er/-est; yang panjang memakai more/most. 'Than' mengawali hal kedua yang dibandingkan."],"pattern":[{"head":[["Type","Jenis"],["Comparative","Komparatif"],["Superlative","Superlatif"]],"rows":[[["short: + er/est","pendek: + er/est"],"cheap{er}","the cheap{est}"],[["-e: + r/st","-e: + r/st"],"nice{r}","the nice{st}"],[["consonant + y → ier","konsonan + y → ier"],"eas{ier}","the eas{iest}"],[["double consonant","konsonan ganda"],"bi{gger}","the bi{ggest}"],[["long: more / most","panjang: more / most"],"{more} expensive","the {most} expensive"],[["irregular","tidak beraturan"],"good → {better}, bad → {worse}, far → {further}","the {best}, the {worst}, the {furthest}"]]}],"examples":[["Jakarta is bigger than Bandung.","Jakarta lebih besar daripada Bandung."],["This is the best coffee in town.","Ini kopi terbaik di kota."],["She is more patient than me.","Dia lebih sabar daripada saya."]],"tip":["Never both: 'more bigger' is wrong. 'As … as' means equal: 'as tall as me'.","Jangan keduanya: 'more bigger' salah. 'As … as' berarti sama: 'as tall as me'."]},{"id":"a2-frequency","title":["Adverbs of frequency","Kata keterangan frekuensi"],"what":["always, usually, often, sometimes, rarely, never say how often. They go before the main verb but after 'be'.","always, usually, often, sometimes, rarely, never menyatakan seberapa sering. Diletakkan sebelum kata kerja utama tetapi setelah 'be'."],"pattern":[{"head":[["Adverb","Kata keterangan"],["How often","Seberapa sering"],["Example","Contoh"]],"rows":[["{always}","100%","I always walk to work."],["{usually}","90%","She usually takes the bus."],["{often}","70%","We often eat out."],["{sometimes}","50%","He's sometimes late."],["{rarely}","10%","They rarely call."],["{never}","0%","I never drink coffee."]]}],"examples":[["I usually get up at six.","Saya biasanya bangun jam enam."],["She is always happy.","Dia selalu senang."],["How often do you exercise?","Seberapa sering kamu berolahraga?"]],"tip":["Position: before the main verb ('I often go'), after 'be' ('I'm often tired').","Posisi: sebelum kata kerja utama ('I often go'), setelah 'be' ('I'm often tired')."]},{"id":"a2-adverbs-manner","title":["Adverbs of manner (-ly)","Kata keterangan cara (-ly)"],"what":["Adjectives describe nouns; adverbs describe verbs (how something is done). Most adverbs add -ly.","Kata sifat menjelaskan kata benda; kata keterangan menjelaskan kata kerja (bagaimana sesuatu dilakukan). Sebagian besar ditambah -ly."],"pattern":[{"head":[["Adjective","Kata sifat"],["Adverb","Kata keterangan"]],"rows":[["slow","slow{ly}"],["careful","careful{ly}"],["easy","eas{ily}"],["good","{well}"],["fast, hard, late",["same: {fast}, {hard}, {late}","sama: {fast}, {hard}, {late}"]]]}],"examples":[["She speaks English well.","Dia berbicara bahasa Inggris dengan baik."],["Please drive carefully.","Tolong menyetir dengan hati-hati."],["He works hard.","Dia bekerja keras."]],"tip":["'Good' is an adjective, 'well' the adverb: 'a good singer' who 'sings well'. 'Hardly' means 'almost not', not 'hard'.","'Good' kata sifat, 'well' kata keterangannya: 'a good singer' yang 'sings well'. 'Hardly' berarti 'hampir tidak', bukan 'keras'."]},{"id":"a2-countable","title":["Countable and uncountable: some, any, much, many","Terhitung dan tak terhitung: some, any, much, many"],"what":["Countable nouns have a plural (apples); uncountable nouns don't (water, money, advice). The quantity words change with the type.","Kata benda terhitung punya bentuk jamak (apples); kata benda tak terhitung tidak (water, money, advice). Kata jumlahnya berbeda menurut jenisnya."],"pattern":[{"head":["",["Countable","Terhitung"],["Uncountable","Tak terhitung"]],"rows":[[["positive","positif"],"{some} apples, {a lot of} apples","{some} water, {a lot of} water"],[["negative / question","negatif / pertanyaan"],"{any} apples","{any} water"],[["how many / much","berapa banyak"],"{How many} apples?","{How much} water?"],[["a little / few","sedikit"],"{a few} apples","{a little} water"]]}],"examples":[["Is there any milk?","Ada susu?"],["I have a few friends here.","Saya punya beberapa teman di sini."],["How much money do you need?","Berapa banyak uang yang kamu butuhkan?"]],"tip":["Uncountable in English: advice, information, news, furniture, luggage, money. No 'an advice', no 'informations'.","Tak terhitung dalam bahasa Inggris: advice, information, news, furniture, luggage, money. Tidak ada 'an advice' atau 'informations'."]},{"id":"a2-object-possessive","title":["Possessive pronouns: mine, yours…","Kata ganti kepemilikan: mine, yours…"],"what":["Possessive pronouns replace 'possessive + noun'. They stand alone, without a noun after them.","Kata ganti kepemilikan menggantikan 'kepemilikan + kata benda'. Berdiri sendiri, tanpa kata benda sesudahnya."],"pattern":[{"head":[["Before a noun","Sebelum kata benda"],["Alone","Berdiri sendiri"]],"rows":[["my book","{mine}"],["your book","{yours}"],["his book","{his}"],["her book","{hers}"],["our book","{ours}"],["their book","{theirs}"]]}],"examples":[["Is this pen yours?","Apakah pulpen ini milikmu?"],["That bag isn't mine.","Tas itu bukan milik saya."],["Their house is bigger than ours.","Rumah mereka lebih besar daripada rumah kami."]],"tip":["No apostrophe: yours, hers, ours, theirs (never your's).","Tanpa apostrof: yours, hers, ours, theirs (bukan your's)."]},{"id":"a2-must-have-to","title":["Must, have to, should","Must, have to, should"],"what":["'Must' and 'have to' express obligation; 'should' gives advice. In the negative they differ a lot: mustn't = forbidden, don't have to = not necessary.","'Must' dan 'have to' menyatakan kewajiban; 'should' memberi saran. Bentuk negatifnya sangat berbeda: mustn't = dilarang, don't have to = tidak perlu."],"pattern":[{"head":[["Form","Bentuk"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{must}",["strong obligation (speaker)","kewajiban kuat (dari pembicara)"],"I must call my mum."],["{have to}",["obligation (rules)","kewajiban (aturan)"],"We have to wear a uniform."],["{mustn't}",["forbidden","dilarang"],"You mustn't smoke here."],["{don't have to}",["not necessary","tidak perlu"],"You don't have to come."],["{should}",["advice","saran"],"You should see a doctor."]]}],"examples":[["Do I have to pay now?","Apakah saya harus bayar sekarang?"],["You should drink more water.","Kamu sebaiknya minum lebih banyak air."],["Students mustn't use phones in exams.","Siswa dilarang memakai ponsel saat ujian."]],"tip":["Past of must/have to = had to: 'I had to work yesterday.'","Bentuk lampau must/have to = had to: 'I had to work yesterday.'"]},{"id":"a2-like-want","title":["Verb patterns: like doing, want to do","Pola kata kerja: like doing, want to do"],"what":["Some verbs are followed by -ing, others by to + base form. Learn each verb with its pattern.","Beberapa kata kerja diikuti -ing, yang lain diikuti to + bentuk dasar. Hafalkan setiap kata kerja beserta polanya."],"pattern":[{"head":[["Pattern","Pola"],["Verbs","Kata kerja"],["Example","Contoh"]],"rows":[["+ -ing","like, love, hate, enjoy, finish, mind","I enjoy {cooking}."],["+ to","want, need, decide, hope, plan, learn","I want {to learn}."],["would like + to",["polite want","keinginan sopan"],"I'd like {to order}."]]}],"examples":[["She enjoys swimming.","Dia senang berenang."],["We decided to stay.","Kami memutuskan untuk tinggal."],["Would you like to come?","Mau ikut?"]],"tip":["'I'd like to…' is the polite form of 'I want to…'. 'Like' + -ing = enjoy in general.","'I'd like to…' adalah bentuk sopan dari 'I want to…'. 'Like' + -ing = suka secara umum."]},{"id":"a2-prep-movement","title":["Prepositions of movement","Kata depan gerak"],"what":["Prepositions that show direction: to, into, out of, across, along, through, up, down, past.","Kata depan yang menunjukkan arah: to, into, out of, across, along, through, up, down, past."],"pattern":[{"head":[["Preposition","Kata depan"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{to}",["towards a place","menuju tempat"],"go to work"],["{into} / {out of}",["enter / leave","masuk / keluar"],"into the room, out of the car"],["{across}",["from one side to the other","menyeberangi"],"walk across the street"],["{through}",["inside from end to end","melewati bagian dalam"],"through the tunnel"],["{along}",["following a line","menyusuri"],"along the river"],["{up} / {down}",["higher / lower","naik / turun"],"up the stairs"],["{past}",["going by","melewati"],"walk past the bank"]]}],"examples":[["She ran into the house.","Dia berlari masuk ke rumah."],["Go along this road and turn left.","Susuri jalan ini lalu belok kiri."],["We walked through the park.","Kami berjalan melewati taman."]],"tip":["No 'to' with home: 'go home', not 'go to home'.","Tanpa 'to' untuk home: 'go home', bukan 'go to home'."]},{"id":"a2-conjunctions","title":["Linking words: and, but, because, so, or","Kata sambung: and, but, because, so, or"],"what":["Conjunctions join ideas. 'Because' gives a reason, 'so' gives a result.","Kata sambung menggabungkan gagasan. 'Because' memberi alasan, 'so' memberi akibat."],"pattern":[{"head":[["Word","Kata"],["Use","Penggunaan"],["Example","Contoh"]],"rows":[["{and}",["adds","menambah"],"I'm tired and hungry."],["{but}",["contrast","kontras"],"It's small but nice."],["{or}",["choice","pilihan"],"Tea or coffee?"],["{because}",["reason","alasan"],"I'm late because the bus was late."],["{so}",["result","akibat"],"The bus was late, so I'm late."]]}],"examples":[["I stayed home because I was ill.","Saya di rumah karena sakit."],["It was raining, so we took a taxi.","Hujan, jadi kami naik taksi."],["He's rich but unhappy.","Dia kaya tetapi tidak bahagia."]],"tip":["Not 'because… so' together: one of them is enough.","Jangan pakai 'because… so' bersamaan: cukup salah satu."]},{"id":"a2-too-enough","title":["Too and enough","Too dan enough"],"what":["'Too' = more than is good (before an adjective). 'Enough' = as much as needed (after an adjective, before a noun).","'Too' = berlebihan (sebelum kata sifat). 'Enough' = cukup (setelah kata sifat, sebelum kata benda)."],"pattern":[{"head":[["Form","Bentuk"],["Example","Contoh"]],"rows":[["{too} + adjective","It's {too} expensive."],["adjective + {enough}","He isn't old {enough}."],["{enough} + noun","We don't have {enough} time."],["{too much / many} + noun","There's {too much} sugar. / {too many} people."]]}],"examples":[["This coffee is too hot to drink.","Kopi ini terlalu panas untuk diminum."],["Is the room big enough?","Apakah ruangannya cukup besar?"],["I ate too much.","Saya makan terlalu banyak."]],"tip":["'Too' is negative: 'It's too beautiful' sounds odd; say 'very beautiful'.","'Too' bermakna negatif: 'It's too beautiful' terdengar aneh; katakan 'very beautiful'."]}]},{"id":"B1","name":["Intermediate","Menengah"],"goal":["Connect past and present, talk about conditions, report what people said, use the passive.","Menghubungkan masa lalu dan sekarang, membahas syarat, menyampaikan ucapan orang lain, memakai kalimat pasif."],"topics":[{"id":"b1-pp-vs-past","title":["Present perfect vs past simple","Present perfect vs past simple"],"what":["Past simple = finished time (yesterday, in 2020, when I was a child). Present perfect = unfinished time or no time given, with a link to now (just, already, yet, since, for).","Past simple = waktu yang sudah selesai (yesterday, in 2020, when I was a child). Present perfect = waktu yang belum selesai atau tanpa keterangan waktu, terhubung dengan sekarang (just, already, yet, since, for)."],"pattern":[{"head":[["Present perfect","Present perfect"],["Past simple","Past simple"]],"rows":[["I {have lived} here for five years. (still here)","I {lived} there for five years. (not now)"],["She {has just left}.","She {left} ten minutes ago."],["{Have} you {finished} yet?","{Did} you {finish} it yesterday?"],["for + period, since + start point","ago, yesterday, last…, in + year"]]}],"examples":[["I've worked here since 2020.","Saya sudah bekerja di sini sejak 2020."],["I worked there in 2019.","Saya bekerja di sana pada 2019."],["Have you eaten yet?","Kamu sudah makan?"]],"tip":["'For' + length of time (for three years), 'since' + starting point (since 2020, since Monday).","'For' + lamanya waktu (for three years), 'since' + titik awal (since 2020, since Monday)."]},{"id":"b1-pp-continuous","title":["Present perfect continuous","Present perfect continuous"],"what":["have/has been + -ing for an activity that started in the past and is still going on, or just stopped with visible results. It stresses duration.","have/has been + -ing untuk kegiatan yang dimulai di masa lalu dan masih berlangsung, atau baru berhenti dengan hasil yang terlihat. Menekankan lamanya."],"pattern":[{"head":[["Use","Penggunaan"],["Example","Contoh"]],"rows":[[["still continuing","masih berlangsung"],"I'{ve been waiting} for an hour."],[["recent, with results","baru saja, dengan hasil"],"You're wet. {Have} you {been running}?"],[["question about duration","pertanyaan tentang lamanya"],"How long {have} you {been learning} English?"]]}],"examples":[["It's been raining all day.","Sudah hujan sepanjang hari."],["She's been working here since May.","Dia sudah bekerja di sini sejak Mei."],["How long have you been waiting?","Sudah berapa lama kamu menunggu?"]],"tip":["Use simple, not continuous, for results counted ('I've written three emails') and with state verbs ('I've known her for years').","Pakai bentuk simple, bukan continuous, untuk hasil yang dihitung ('I've written three emails') dan kata kerja keadaan ('I've known her for years')."]},{"id":"b1-past-perfect","title":["Past perfect","Past perfect"],"what":["had + past participle for something that happened before another past moment.","had + partisip lampau untuk sesuatu yang terjadi sebelum momen lampau lainnya."],"pattern":[{"head":[["Earlier action","Tindakan lebih awal"],["Later action","Tindakan berikutnya"]],"rows":[["The train {had left}","when we {arrived}."],["I {had never seen} snow","before I {went} to Prague."],["After she {had eaten},","she {went} to bed."]]}],"examples":[["When I got home, everyone had gone to bed.","Ketika saya pulang, semua orang sudah tidur."],["I'd forgotten my keys.","Saya lupa membawa kunci (sebelumnya)."],["Had you met him before?","Apakah kamu pernah bertemu dia sebelumnya?"]],"tip":["Not needed when 'before/after' already makes the order clear: 'I left before he arrived' is fine.","Tidak wajib jika 'before/after' sudah memperjelas urutan: 'I left before he arrived' sudah benar."]},{"id":"b1-used-to","title":["Used to and would (past habits)","Used to dan would (kebiasaan lampau)"],"what":["'Used to' + base form for past habits and states that are no longer true. 'Would' can also describe repeated past actions, but not states.","'Used to' + bentuk dasar untuk kebiasaan dan keadaan lampau yang sekarang tidak lagi berlaku. 'Would' juga bisa untuk tindakan lampau yang berulang, tetapi tidak untuk keadaan."],"pattern":[{"head":[["Form","Bentuk"],["Example","Contoh"]],"rows":[[["Positive","Positif"],"I {used to} smoke."],[["Negative","Negatif"],"I {didn't use to} like coffee."],[["Question","Pertanyaan"],"{Did} you {use to} live here?"],[["would (actions only)","would (hanya tindakan)"],"Every summer we {would} go to the beach."]]}],"examples":[["We used to live in Medan.","Dulu kami tinggal di Medan."],["There used to be a cinema here.","Dulu ada bioskop di sini."],["He didn't use to work so hard.","Dulu dia tidak bekerja sekeras ini."]],"tip":["Don't confuse with 'be used to + -ing' (be familiar with): 'I'm used to getting up early.'","Jangan tertukar dengan 'be used to + -ing' (sudah terbiasa): 'I'm used to getting up early.'"]},{"id":"b1-first-cond","title":["First conditional (real future)","Kalimat pengandaian tipe 1 (masa depan nyata)"],"what":["If + present simple, will + base form: a real, possible situation in the future and its result.","If + present simple, will + bentuk dasar: situasi masa depan yang nyata dan mungkin, beserta akibatnya."],"pattern":[{"head":[["If-clause","Anak kalimat if"],["Main clause","Kalimat utama"]],"rows":[["If it {rains},","we'{ll stay} at home."],["If you {don't hurry},","you'{ll miss} the bus."],["Unless you {study},","you {won't pass}."]]}],"examples":[["If I see him, I'll tell him.","Kalau saya bertemu dia, saya akan memberitahunya."],["What will you do if you lose your job?","Apa yang akan kamu lakukan kalau kehilangan pekerjaan?"],["Call me when you arrive.","Telepon saya saat kamu tiba."]],"tip":["No 'will' in the if-clause: 'If it rains', not 'If it will rain'. The same after when, as soon as, before, until.","Tidak ada 'will' di anak kalimat if: 'If it rains', bukan 'If it will rain'. Sama setelah when, as soon as, before, until."]},{"id":"b1-second-cond","title":["Second conditional (unreal present)","Kalimat pengandaian tipe 2 (tidak nyata sekarang)"],"what":["If + past simple, would + base form: imagined or unlikely situations now or in the future. The past form doesn't mean past time.","If + past simple, would + bentuk dasar: situasi yang dibayangkan atau tidak mungkin sekarang atau nanti. Bentuk lampau di sini tidak berarti waktu lampau."],"pattern":[{"head":[["If-clause","Anak kalimat if"],["Main clause","Kalimat utama"]],"rows":[["If I {had} more money,","I {would travel}."],["If I {were} you,","I {wouldn't do} that."],["If she {lived} closer,","we'{d see} her more often."]]}],"examples":[["If I won the lottery, I'd buy a house.","Seandainya saya menang lotre, saya akan membeli rumah."],["What would you do if you were me?","Apa yang akan kamu lakukan seandainya kamu jadi saya?"],["I'd help you if I could.","Saya akan membantumu kalau saya bisa."]],"tip":["'If I were you' is the standard advice form; 'were' is used for all persons in formal English.","'If I were you' adalah bentuk baku untuk memberi saran; 'were' dipakai untuk semua persona dalam bahasa Inggris formal."]},{"id":"b1-future-forms","title":["Future forms: will, going to, present continuous","Bentuk masa depan: will, going to, present continuous"],"what":["English has several ways to talk about the future. The choice depends on how fixed the plan is.","Bahasa Inggris punya beberapa cara membicarakan masa depan. Pilihannya tergantung seberapa pasti rencananya."],"pattern":[{"head":[["Form","Bentuk"],["Use","Penggunaan"],["Example","Contoh"]],"rows":[["present continuous",["fixed arrangement (time, place)","janji/pengaturan pasti (waktu, tempat)"],"I'{m meeting} Tom at six."],["going to",["plan / intention; evidence","rencana / niat; bukti"],"I'{m going to} look for a new job."],["will",["instant decision, promise, prediction","keputusan seketika, janji, perkiraan"],"I'{ll} call you later."],["present simple",["timetables","jadwal"],"The train {leaves} at 7:15."]]}],"examples":[["What are you doing this weekend?","Apa rencanamu akhir pekan ini?"],["The film starts at eight.","Filmnya mulai jam delapan."],["I think you'll love it.","Saya rasa kamu akan menyukainya."]],"tip":["Arrangements with other people → present continuous: 'We're having dinner with them on Friday.'","Pengaturan dengan orang lain → present continuous: 'We're having dinner with them on Friday.'"]},{"id":"b1-passive","title":["Passive voice (present and past)","Kalimat pasif (present dan past)"],"what":["be + past participle when the action matters more than who did it. Add 'by' to name the doer.","be + partisip lampau ketika tindakannya lebih penting daripada pelakunya. Tambahkan 'by' untuk menyebut pelaku."],"pattern":[{"head":[["Tense","Kala"],["Active","Aktif"],["Passive","Pasif"]],"rows":[["present simple","They make cars here.","Cars {are made} here."],["past simple","Someone stole my bike.","My bike {was stolen}."],["present perfect","They have sold the house.","The house {has been sold}."],["with will / can","They will finish it.","It {will be finished}."]]}],"examples":[["English is spoken all over the world.","Bahasa Inggris dituturkan di seluruh dunia."],["The bridge was built in 1990.","Jembatan itu dibangun pada 1990."],["Was it written by a famous author?","Apakah itu ditulis oleh penulis terkenal?"]],"tip":["Every passive needs a form of 'be': 'It was made', not 'It made' (which means something different).","Setiap kalimat pasif butuh bentuk 'be': 'It was made', bukan 'It made' (artinya lain)."]},{"id":"b1-relative","title":["Relative clauses: who, which, that, where, whose","Anak kalimat relatif: who, which, that, where, whose"],"what":["Relative clauses describe a noun. 'Who' for people, 'which' for things, 'that' for both, 'where' for places, 'whose' for possession.","Anak kalimat relatif menjelaskan kata benda. 'Who' untuk orang, 'which' untuk benda, 'that' untuk keduanya, 'where' untuk tempat, 'whose' untuk kepemilikan."],"pattern":[{"head":[["Word","Kata"],["For","Untuk"],["Example","Contoh"]],"rows":[["{who}",["people","orang"],"the woman {who} lives next door"],["{which}",["things","benda"],"the book {which} I bought"],["{that}",["people or things","orang atau benda"],"the car {that} broke down"],["{where}",["places","tempat"],"the hotel {where} we stayed"],["{whose}",["possession","kepemilikan"],"the man {whose} wallet was stolen"]]}],"examples":[["That's the doctor who helped me.","Itu dokter yang menolong saya."],["The phone (that) I bought is broken.","Ponsel yang saya beli rusak."],["This is the café where we met.","Ini kafe tempat kami bertemu."]],"tip":["When the relative word is the object, you can leave it out: 'the phone (that) I bought'.","Jika kata relatifnya objek, boleh dihilangkan: 'the phone (that) I bought'."]},{"id":"b1-reported","title":["Reported speech (basics)","Kalimat tidak langsung (dasar)"],"what":["When reporting with 'said' or 'told', the tense usually moves one step back, and pronouns and time words change.","Saat melaporkan dengan 'said' atau 'told', kala biasanya mundur satu langkah, dan kata ganti serta keterangan waktu berubah."],"pattern":[{"head":[["Direct","Langsung"],["Reported","Tidak langsung"]],"rows":[["\"I {am} tired.\"","She said (that) she {was} tired."],["\"I {like} it.\"","He said he {liked} it."],["\"We {will} help.\"","They said they {would} help."],["\"I {saw} him.\"","She said she {had seen} him."],["\"I {can} come.\"","He told me he {could} come."]]}],"examples":[["He said he was busy.","Dia bilang dia sedang sibuk."],["She told me she would call.","Dia bilang kepada saya bahwa dia akan menelepon."],["They said they had finished.","Mereka bilang sudah selesai."]],"tip":["'Tell' needs a person: 'She told me…'. 'Say' doesn't: 'She said (to me)…'.","'Tell' butuh orang: 'She told me…'. 'Say' tidak: 'She said (to me)…'."]},{"id":"b1-gerund-inf","title":["Gerunds and infinitives","Gerund dan infinitif"],"what":["After prepositions and certain verbs, use -ing. After other verbs and adjectives, use to + base form. Some verbs change meaning.","Setelah kata depan dan kata kerja tertentu, pakai -ing. Setelah kata kerja dan kata sifat lain, pakai to + bentuk dasar. Beberapa kata kerja berubah arti."],"pattern":[{"head":[["Pattern","Pola"],["Examples","Contoh"]],"rows":[[["preposition + -ing","kata depan + -ing"],"interested in {learning}, good at {cooking}, before {leaving}"],[["-ing as subject","-ing sebagai subjek"],"{Swimming} is good for you."],[["verb + -ing","kata kerja + -ing"],"avoid, suggest, keep, consider, can't stand"],[["verb + to","kata kerja + to"],"agree, promise, refuse, manage, seem, offer"],[["adjective + to","kata sifat + to"],"It's easy {to learn}. I'm happy {to help}."]]}],"examples":[["Thank you for coming.","Terima kasih sudah datang."],["He refused to answer.","Dia menolak menjawab."],["I'm thinking about moving.","Saya sedang mempertimbangkan untuk pindah."]],"tip":["After a preposition, never 'to + verb': 'interested in learning', not 'interested in to learn'.","Setelah kata depan, jangan 'to + verb': 'interested in learning', bukan 'interested in to learn'."]},{"id":"b1-modals-possibility","title":["Modals of possibility: might, may, could, must, can't","Modal kemungkinan: might, may, could, must, can't"],"what":["These modals show how sure you are. 'Must' = almost certainly true, 'can't' = almost certainly not true, 'might/may/could' = possible.","Modal ini menunjukkan seberapa yakin kamu. 'Must' = hampir pasti benar, 'can't' = hampir pasti tidak benar, 'might/may/could' = mungkin."],"pattern":[{"head":[["Certainty","Kepastian"],["Modal","Modal"],["Example","Contoh"]],"rows":[["95% ✓","{must}","She's not answering. She {must} be asleep."],["50%","{might / may / could}","He {might} be at work."],["95% ✗","{can't}","That {can't} be true!"]]}],"examples":[["They may be late.","Mereka mungkin terlambat."],["You must be tired after the trip.","Kamu pasti lelah setelah perjalanan."],["It can't be him; he's in Bali.","Tidak mungkin dia; dia di Bali."]],"tip":["The opposite of 'must be' (sure) is 'can't be', not 'mustn't be'.","Kebalikan dari 'must be' (yakin) adalah 'can't be', bukan 'mustn't be'."]},{"id":"b1-question-tags","title":["Question tags","Question tag"],"what":["Short questions at the end of a sentence to check or invite agreement. Positive sentence → negative tag, and the reverse. The tag repeats the auxiliary.","Pertanyaan pendek di akhir kalimat untuk memastikan atau meminta persetujuan. Kalimat positif → tag negatif, dan sebaliknya. Tag mengulang kata bantu."],"pattern":[{"head":[["Sentence","Kalimat"],["Tag","Tag"]],"rows":[["You're tired,","{aren't you}?"],["She lives here,","{doesn't she}?"],["They didn't come,","{did they}?"],["You can swim,","{can't you}?"],["I'm late,","{aren't I}?"],["Let's go,","{shall we}?"]]}],"examples":[["It's cold today, isn't it?","Hari ini dingin, ya?"],["You haven't seen my keys, have you?","Kamu tidak melihat kunci saya, kan?"],["He works here, doesn't he?","Dia bekerja di sini, kan?"]],"tip":["English has no all-purpose tag like 'right?'/'ya?' in formal speech; the tag must match the verb.","Bahasa Inggris tidak punya tag serbaguna seperti 'ya?' dalam bahasa formal; tag harus cocok dengan kata kerjanya."]},{"id":"b1-so-such","title":["So and such","So dan such"],"what":["Both add emphasis. 'So' + adjective/adverb; 'such' + (a/an) + adjective + noun. Often followed by 'that' + result.","Keduanya menambah penekanan. 'So' + kata sifat/keterangan; 'such' + (a/an) + kata sifat + kata benda. Sering diikuti 'that' + akibat."],"pattern":[{"head":[["Form","Bentuk"],["Example","Contoh"]],"rows":[["{so} + adjective","The film was {so} boring."],["{such} a/an + adj + noun","It was {such} a boring film."],["{such} + adj + plural/uncountable","They're {such} nice people."],["{so} … that","I was {so} tired that I fell asleep."],["{so} much / many","There were {so many} people."]]}],"examples":[["She's so kind.","Dia sangat baik."],["It was such a good day!","Hari yang sangat menyenangkan!"],["It was so hot that we stayed inside.","Begitu panas sehingga kami tinggal di dalam."]],"tip":["'Such' needs a noun; 'so' doesn't: 'so beautiful', 'such a beautiful place'.","'Such' butuh kata benda; 'so' tidak: 'so beautiful', 'such a beautiful place'."]},{"id":"b1-phrasal","title":["Phrasal verbs (common)","Phrasal verb (umum)"],"what":["Verb + particle with a new meaning. Some can be separated by the object; with a pronoun object they must be separated.","Kata kerja + partikel dengan arti baru. Sebagian bisa dipisah oleh objek; jika objeknya kata ganti, harus dipisah."],"pattern":[{"head":[["Phrasal verb","Phrasal verb"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{give up}",["stop trying / quit","menyerah / berhenti"],"Don't give up!"],["{look after}",["take care of","merawat"],"She looks after her mum."],["{find out}",["discover","mencari tahu"],"I found out the truth."],["{turn on / off}",["start / stop a device","menyalakan / mematikan"],"Turn {it off}, please."],["{get up}",["leave bed","bangun"],"I get up at six."],["{put off}",["postpone","menunda"],"They put off the meeting."]]}],"examples":[["Could you turn the music down?","Bisa kecilkan musiknya?"],["I'm looking forward to the trip.","Saya menantikan perjalanan ini."],["He gave up smoking last year.","Dia berhenti merokok tahun lalu."]],"tip":["Pronoun goes in the middle: 'turn it off', not 'turn off it'.","Kata ganti diletakkan di tengah: 'turn it off', bukan 'turn off it'."]},{"id":"b1-so-neither","title":["So do I / neither do I; too / either","So do I / neither do I; too / either"],"what":["Short ways to agree. Positive: 'so + auxiliary + subject' or '… too'. Negative: 'neither + auxiliary + subject' or '… not … either'.","Cara singkat untuk menyatakan persetujuan. Positif: 'so + kata bantu + subjek' atau '… too'. Negatif: 'neither + kata bantu + subjek' atau '… not … either'."],"pattern":[{"head":[["Statement","Pernyataan"],["Agree","Setuju"],["Also","Juga"]],"rows":[["I like tea.","{So do I}.","I like tea {too}."],["I'm tired.","{So am I}.","I'm tired {too}."],["I don't eat meat.","{Neither do I}.","I don't {either}."],["I can't swim.","{Neither can I}.","I can't {either}."],["I went home.","{So did I}.","I went home {too}."]]}],"examples":[["\"I've never been there.\" \"Neither have I.\"","\"Saya belum pernah ke sana.\" \"Saya juga belum.\""],["\"I love this song.\" \"So do I!\"","\"Saya suka lagu ini.\" \"Saya juga!\""],["She doesn't drive either.","Dia juga tidak menyetir."]],"tip":["Match the auxiliary: 'I'm hungry' → 'So am I' (not 'So do I').","Cocokkan kata bantunya: 'I'm hungry' → 'So am I' (bukan 'So do I')."]}]},{"id":"B2","name":["Upper intermediate","Menengah atas"],"goal":["Talk about regrets and imagined pasts, report precisely, link ideas, use advanced passive and verb patterns.","Membahas penyesalan dan masa lalu yang dibayangkan, melaporkan dengan tepat, menghubungkan gagasan, memakai pasif dan pola kata kerja lanjutan."],"topics":[{"id":"b2-third-cond","title":["Third conditional (unreal past)","Pengandaian tipe 3 (tidak nyata di masa lalu)"],"what":["If + past perfect, would have + past participle: imagining a different past and its result. Often used for regrets.","If + past perfect, would have + partisip lampau: membayangkan masa lalu yang berbeda beserta akibatnya. Sering dipakai untuk penyesalan."],"pattern":[{"head":[["If-clause","Anak kalimat if"],["Main clause","Kalimat utama"]],"rows":[["If I {had known},","I {would have come}."],["If she {hadn't missed} the bus,","she {wouldn't have been} late."],["If we {had left} earlier,","we {could have caught} the train."]]}],"examples":[["If you'd told me, I would have helped.","Seandainya kamu memberi tahu saya, saya pasti sudah membantu."],["What would you have done?","Apa yang akan kamu lakukan (waktu itu)?"],["I wouldn't have passed without your help.","Tanpa bantuanmu saya tidak akan lulus."]],"tip":["'If I would have known' is a common mistake: the if-clause takes the past perfect ('If I had known').","'If I would have known' adalah kesalahan umum: anak kalimat if memakai past perfect ('If I had known')."]},{"id":"b2-mixed-cond","title":["Mixed conditionals","Pengandaian campuran"],"what":["Combine times: a past condition with a present result, or a present (permanent) condition with a past result.","Menggabungkan waktu: syarat lampau dengan akibat sekarang, atau syarat sekarang (tetap) dengan akibat lampau."],"pattern":[{"head":[["Type","Jenis"],["Example","Contoh"]],"rows":[[["past condition → present result","syarat lampau → akibat sekarang"],"If I {had taken} the job, I {would be} rich now."],[["present condition → past result","syarat sekarang → akibat lampau"],"If I {spoke} French, I {would have understood} him."]]}],"examples":[["If she hadn't moved abroad, she'd be living near us now.","Seandainya dia tidak pindah ke luar negeri, dia sekarang tinggal dekat kami."],["If he were more careful, he wouldn't have crashed.","Seandainya dia lebih berhati-hati, dia tidak akan menabrak."]],"tip":["Check the time of each half separately; each half keeps its own conditional form.","Periksa waktu setiap bagian secara terpisah; setiap bagian memakai bentuk pengandaiannya sendiri."]},{"id":"b2-wish","title":["Wish and if only","Wish dan if only"],"what":["Express regret or desire. The verb after 'wish' moves one step into the past.","Menyatakan penyesalan atau keinginan. Kata kerja setelah 'wish' mundur satu langkah ke masa lalu."],"pattern":[{"head":[["About","Tentang"],["Form","Bentuk"],["Example","Contoh"]],"rows":[[["the present","sekarang"],"wish + past simple","I wish I {had} a car."],[["the past (regret)","masa lalu (penyesalan)"],"wish + past perfect","I wish I {hadn't said} that."],[["annoying behaviour","perilaku yang menjengkelkan"],"wish + would","I wish you {would stop} talking."],[["ability","kemampuan"],"wish + could","I wish I {could} swim."]]}],"examples":[["If only I'd studied harder!","Seandainya saya belajar lebih giat!"],["She wishes she lived by the sea.","Dia berharap tinggal di tepi laut."],["I wish it would stop raining.","Saya berharap hujannya berhenti."]],"tip":["Don't use 'would' about yourself: 'I wish I had', not 'I wish I would have'.","Jangan pakai 'would' untuk dirimu sendiri: 'I wish I had', bukan 'I wish I would have'."]},{"id":"b2-passive-adv","title":["Advanced passive","Pasif lanjutan"],"what":["Passive in all tenses and with modals, the 'get' passive, and impersonal reporting structures (It is said that… / He is said to…).","Pasif di semua kala dan dengan modal, pasif dengan 'get', dan struktur pelaporan impersonal (It is said that… / He is said to…)."],"pattern":[{"head":[["Form","Bentuk"],["Example","Contoh"]],"rows":[[["continuous","continuous"],"The road {is being repaired}."],[["modal","modal"],"It {must be done} today."],[["modal perfect","modal perfect"],"It {should have been sent} yesterday."],[["get passive","pasif get"],"He {got fired}."],[["reporting: it","pelaporan: it"],"{It is believed that} he left."],[["reporting: subject","pelaporan: subjek"],"He {is believed to have} left."]]}],"examples":[["The results will be announced tomorrow.","Hasilnya akan diumumkan besok."],["She is thought to be the best candidate.","Dia dianggap kandidat terbaik."],["My car is being serviced.","Mobil saya sedang diservis."]],"tip":["Past reporting: 'He is said to have left' (the leaving was earlier).","Pelaporan lampau: 'He is said to have left' (kepergiannya lebih dulu)."]},{"id":"b2-reported-adv","title":["Reported questions, commands and reporting verbs","Pertanyaan, perintah tidak langsung dan kata kerja pelaporan"],"what":["Reported questions use statement word order. Commands use tell/ask + to. Reporting verbs like suggest, warn, deny have their own patterns.","Pertanyaan tidak langsung memakai urutan kata pernyataan. Perintah memakai tell/ask + to. Kata kerja pelaporan seperti suggest, warn, deny punya pola sendiri."],"pattern":[{"head":[["Type","Jenis"],["Direct","Langsung"],["Reported","Tidak langsung"]],"rows":[[["wh-question","pertanyaan wh"],"\"Where do you live?\"","She asked where {I lived}."],[["yes/no question","pertanyaan ya/tidak"],"\"Are you ready?\"","He asked {if/whether} I was ready."],[["command","perintah"],"\"Sit down.\"","She told me {to sit} down."],[["suggest","suggest"],"\"Let's go.\"","He suggested {going}."],[["warn / deny / offer","warn / deny / offer"],"\"I didn't do it.\"","He denied {doing} it."]]}],"examples":[["She asked me what time it was.","Dia bertanya kepada saya jam berapa."],["They warned us not to swim there.","Mereka memperingatkan kami agar tidak berenang di sana."],["He offered to drive me home.","Dia menawarkan diri mengantar saya pulang."]],"tip":["No question order and no question mark: 'She asked where I lived', not 'where did I live?'.","Tanpa urutan pertanyaan dan tanpa tanda tanya: 'She asked where I lived', bukan 'where did I live?'."]},{"id":"b2-non-defining","title":["Non-defining relative clauses","Anak kalimat relatif nondefinitif"],"what":["Extra information about a noun that is already identified. Set off by commas; 'that' is not allowed; the relative word can't be left out.","Informasi tambahan tentang kata benda yang sudah jelas. Diapit koma; 'that' tidak boleh dipakai; kata relatifnya tidak boleh dihilangkan."],"pattern":[{"head":[["Type","Jenis"],["Example","Contoh"]],"rows":[[["defining (no commas)","definitif (tanpa koma)"],"The man {who lives next door} is a doctor."],[["non-defining (commas)","nondefinitif (koma)"],"My father, {who is 70}, still works."],[["which = the whole idea","which = seluruh gagasan"],"He passed, {which surprised everyone}."],[["quantity + of whom/which","jumlah + of whom/which"],"I have two brothers, {both of whom} live abroad."]]}],"examples":[["Prague, which is the capital, is beautiful.","Praha, yang merupakan ibu kota, sangat indah."],["My sister, whose husband is Czech, lives in Brno.","Kakak saya, yang suaminya orang Ceko, tinggal di Brno."]],"tip":["Never 'that' after a comma: 'Prague, which is…', not 'Prague, that is…'.","Jangan 'that' setelah koma: 'Prague, which is…', bukan 'Prague, that is…'."]},{"id":"b2-future-cont-perf","title":["Future continuous and future perfect","Future continuous dan future perfect"],"what":["Future continuous (will be + -ing): in progress at a future time. Future perfect (will have + past participle): completed before a future time.","Future continuous (will be + -ing): sedang berlangsung pada waktu tertentu di masa depan. Future perfect (will have + partisip lampau): sudah selesai sebelum waktu tertentu di masa depan."],"pattern":[{"head":[["Form","Bentuk"],["Example","Contoh"]],"rows":[["will be + -ing","This time tomorrow I'{ll be flying} to Bali."],["will have + pp","By June I'{ll have finished} my degree."],["will have been + -ing","By May I'{ll have been working} here for ten years."]]}],"examples":[["Don't call at 8 — we'll be having dinner.","Jangan telepon jam 8 — kami sedang makan malam."],["By the time you arrive, I'll have left.","Saat kamu tiba, saya sudah pergi."],["Will you be using the car tonight?","Apakah kamu akan memakai mobil malam ini?"]],"tip":["'By' + time often signals future perfect: 'by Friday', 'by the time…'.","'By' + waktu sering menandakan future perfect: 'by Friday', 'by the time…'."]},{"id":"b2-modals-past","title":["Modals in the past: should have, must have, might have…","Modal lampau: should have, must have, might have…"],"what":["modal + have + past participle for criticism, deduction and possibility about the past.","modal + have + partisip lampau untuk kritik, kesimpulan dan kemungkinan tentang masa lalu."],"pattern":[{"head":[["Form","Bentuk"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{should have} + pp",["it was a good idea but didn't happen","seharusnya (tetapi tidak terjadi)"],"You should have told me."],["{must have} + pp",["almost certain","hampir pasti"],"She must have forgotten."],["{can't / couldn't have} + pp",["impossible","tidak mungkin"],"He can't have seen us."],["{might / may / could have} + pp",["possible","mungkin"],"They might have got lost."],["{needn't have} + pp",["did it, but it wasn't necessary","sudah dilakukan, padahal tidak perlu"],"You needn't have brought food."]]}],"examples":[["I should have listened to you.","Seharusnya saya mendengarkanmu."],["The ground is wet; it must have rained.","Tanahnya basah; pasti tadi hujan."],["She could have been hurt!","Dia bisa saja terluka!"]],"tip":["Say 'should have' (should've), never 'should of'.","Katakan 'should have' (should've), jangan 'should of'."]},{"id":"b2-linking","title":["Linking contrast: although, despite, however, whereas","Penghubung kontras: although, despite, however, whereas"],"what":["Words that show contrast take different structures: a clause, a noun/-ing, or a new sentence.","Kata-kata kontras memakai struktur berbeda: anak kalimat, kata benda/-ing, atau kalimat baru."],"pattern":[{"head":[["Word","Kata"],["Followed by","Diikuti"],["Example","Contoh"]],"rows":[["{although / even though}",["a clause","anak kalimat"],"Although it rained, we went out."],["{despite / in spite of}",["noun or -ing","kata benda atau -ing"],"Despite the rain / Despite being tired…"],["{however}",["new sentence, comma","kalimat baru, koma"],"It rained. However, we went out."],["{whereas / while}",["clause (comparison)","anak kalimat (perbandingan)"],"I like tea, whereas she prefers coffee."]]}],"examples":[["Even though he was ill, he came to work.","Walaupun sakit, dia datang bekerja."],["In spite of the traffic, we arrived on time.","Meskipun macet, kami tiba tepat waktu."],["The plan is good. However, it's expensive.","Rencananya bagus. Namun, mahal."]],"tip":["'Despite of' doesn't exist: say 'despite' or 'in spite of'.","'Despite of' tidak ada: katakan 'despite' atau 'in spite of'."]},{"id":"b2-articles-adv","title":["Articles: advanced rules","Artikel: aturan lanjutan"],"what":["'The' with unique things, superlatives, rivers, seas and some countries; no article with most countries, cities, meals, languages and general abstract nouns.","'The' untuk hal yang unik, superlatif, sungai, laut dan beberapa negara; tanpa artikel untuk sebagian besar negara, kota, waktu makan, bahasa dan kata benda abstrak umum."],"pattern":[{"head":[["Use 'the'","Pakai 'the'"],["No article","Tanpa artikel"]],"rows":[["the UK, the USA, the Netherlands","Indonesia, France, Japan"],["the Thames, the Pacific, the Alps","Lake Toba, Mount Bromo"],["the best, the first, the same","breakfast, lunch, dinner"],["the rich, the elderly (groups)","English, Czech (languages)"],["play the piano (instruments)","play football (sports)"],["the life of Mozart (specific)","Life is short. (general)"]]}],"examples":[["She plays the violin.","Dia bermain biola."],["Have you been to the Philippines?","Pernah ke Filipina?"],["Love is all you need.","Cinta adalah segala yang kamu butuhkan."]],"tip":["General ideas take no article: 'Money isn't everything', 'Children need sleep'.","Gagasan umum tanpa artikel: 'Money isn't everything', 'Children need sleep'."]},{"id":"b2-verb-patterns","title":["Verbs that change meaning: remember, stop, try…","Kata kerja yang berubah arti: remember, stop, try…"],"what":["Some verbs take both -ing and to + base form, with a different meaning.","Beberapa kata kerja bisa diikuti -ing dan to + bentuk dasar, dengan arti berbeda."],"pattern":[{"head":[["Verb","Kata kerja"],["+ -ing","+ -ing"],["+ to","+ to"]],"rows":[["remember",["memory of the past: I remember {locking} it.","ingatan: saya ingat sudah mengunci."],["don't forget: Remember {to lock} it.","jangan lupa: ingat untuk mengunci."]],["stop",["end an activity: I stopped {smoking}.","berhenti melakukan."],["pause to do: I stopped {to smoke}.","berhenti untuk melakukan."]],["try",["experiment: Try {restarting} it.","coba (sebagai cara)."],["make an effort: I tried {to open} it.","berusaha."]],["regret",["sorry about the past: I regret {saying} it.","menyesal telah."],["formal bad news: We regret {to inform} you…","dengan menyesal memberitahukan."]]]}],"examples":[["I'll never forget meeting her.","Saya tidak akan pernah lupa saat bertemu dia."],["Don't forget to call your mum.","Jangan lupa menelepon ibumu."],["He stopped to buy coffee.","Dia berhenti untuk membeli kopi."]],"tip":["-ing usually looks back (something that happened); 'to' usually looks forward (something to do).","-ing biasanya melihat ke belakang (sudah terjadi); 'to' biasanya ke depan (akan dilakukan)."]},{"id":"b2-quantifiers","title":["Quantifiers: each, every, both, either, neither, all, none","Penunjuk jumlah: each, every, both, either, neither, all, none"],"what":["Words for 'all/none/one of two'. 'Each/every' take a singular noun; 'both' is for two; 'either/neither' for one of two.","Kata untuk 'semua/tidak satu pun/salah satu dari dua'. 'Each/every' diikuti kata benda tunggal; 'both' untuk dua; 'either/neither' untuk salah satu dari dua."],"pattern":[{"head":[["Word","Kata"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{every / each}",["all, one by one (+ singular)","setiap (+ tunggal)"],"Every student has a book."],["{both}",["the two","keduanya"],"Both answers are correct."],["{either}",["one or the other","salah satu"],"You can take either bus."],["{neither}",["not one and not the other","bukan keduanya"],"Neither answer is right."],["{all / none}",["everything / not one (3+)","semua / tidak satu pun (3+)"],"None of the shops were open."]]}],"examples":[["Each room has a balcony.","Setiap kamar punya balkon."],["Neither of my parents speaks English.","Kedua orang tua saya tidak bisa berbahasa Inggris."],["Both of us were tired.","Kami berdua lelah."]],"tip":["'Every' + singular verb: 'Everyone is here', 'Every child needs love'.","'Every' + kata kerja tunggal: 'Everyone is here', 'Every child needs love'."]},{"id":"b2-causative","title":["Causative: have / get something done","Kausatif: have / get something done"],"what":["When someone else does a service for you: have/get + object + past participle.","Ketika orang lain melakukan suatu layanan untukmu: have/get + objek + partisip lampau."],"pattern":[{"head":[["Form","Bentuk"],["Example","Contoh"]],"rows":[["have + object + pp","I {had my hair cut}."],["get + object + pp (informal)","We need to {get the car fixed}."],[["bad experience","pengalaman buruk"],"She {had her bag stolen}."],["have + person + base form","I'll {have the porter carry} it."]]}],"examples":[["We're having our kitchen redone.","Dapur kami sedang direnovasi."],["Where do you get your nails done?","Kamu biasa merawat kuku di mana?"],["He had his passport stolen.","Paspornya dicuri."]],"tip":["'I cut my hair' = I did it myself. 'I had my hair cut' = a hairdresser did it.","'I cut my hair' = saya memotongnya sendiri. 'I had my hair cut' = dipotong oleh tukang cukur."]}]},{"id":"C1","name":["Advanced","Mahir"],"goal":["Add emphasis and nuance: inversion, cleft sentences, participle clauses, hedging, ellipsis and formal structures.","Menambahkan penekanan dan nuansa: inversi, kalimat celah, klausa partisip, bahasa berhati-hati, elipsis dan struktur formal."],"topics":[{"id":"c1-inversion","title":["Inversion after negative adverbials","Inversi setelah keterangan negatif"],"what":["After a negative or limiting expression at the start (Never, Rarely, Not only, No sooner, Only then…), the auxiliary comes before the subject, as in a question. Formal and emphatic.","Setelah ungkapan negatif atau pembatas di awal kalimat (Never, Rarely, Not only, No sooner, Only then…), kata kerja bantu mendahului subjek, seperti dalam pertanyaan. Formal dan menekankan."],"pattern":[{"head":[["Opening","Pembuka"],["Example","Contoh"]],"rows":[["Never (before)","Never {have I seen} such a mess."],["Rarely / Seldom","Rarely {does she} complain."],["Not only … but also","Not only {did he} lie, but he also stole."],["No sooner … than","No sooner {had we} arrived than it rained."],["Hardly / Scarcely … when","Hardly {had I} sat down when the phone rang."],["Only then / Only when…","Only then {did I} understand."],["Under no circumstances","Under no circumstances {should you} open it."],["Little","Little {did they} know what was coming."]]}],"examples":[["Not until midnight did they finish.","Baru tengah malam mereka selesai."],["At no time was the public in danger.","Masyarakat sama sekali tidak dalam bahaya."],["Seldom have I heard such nonsense.","Jarang sekali saya mendengar omong kosong seperti itu."]],"tip":["Use 'do/does/did' when there is no other auxiliary: 'Rarely does she…', 'Only then did I…'.","Pakai 'do/does/did' bila tidak ada kata kerja bantu lain: 'Rarely does she…', 'Only then did I…'."]},{"id":"c1-cleft","title":["Cleft sentences: It is … that / What … is","Kalimat celah: It is … that / What … is"],"what":["Split a sentence to focus on one part. 'It was X that…' highlights X; 'What I need is…' puts the focus at the end.","Memecah kalimat untuk menonjolkan satu bagian. 'It was X that…' menonjolkan X; 'What I need is…' menaruh fokus di akhir."],"pattern":[{"head":[["Type","Jenis"],["Neutral","Netral"],["Cleft","Celah"]],"rows":[["It-cleft","Tom broke the window.","{It was Tom who} broke the window."],["It-cleft (time)","I met her in 2010.","{It was in 2010 that} I met her."],["What-cleft","I need a holiday.","{What I need is} a holiday."],["What … do","He complained.","{What he did was} complain."],["All / The thing","I want peace.","{All I want is} peace."],["The reason why","I left because…","{The reason (why) I left was that}…"]]}],"examples":[["It's not the money that worries me, it's the time.","Yang membuat saya khawatir bukan uangnya, melainkan waktunya."],["What surprised me was his reaction.","Yang mengejutkan saya adalah reaksinya."],["What you should do is apologise.","Yang sebaiknya kamu lakukan adalah meminta maaf."]],"tip":["After 'What … did was', use the base form: 'What he did was complain' (not 'complained').","Setelah 'What … did was', pakai bentuk dasar: 'What he did was complain' (bukan 'complained')."]},{"id":"c1-participle","title":["Participle clauses","Klausa partisip"],"what":["-ing, past participle or 'having + pp' replace a full clause to sound concise. The subject must be the same as in the main clause.","-ing, partisip lampau atau 'having + pp' menggantikan anak kalimat lengkap agar ringkas. Subjeknya harus sama dengan kalimat utama."],"pattern":[{"head":[["Form","Bentuk"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["-ing",["at the same time / because (active)","bersamaan / karena (aktif)"],"{Feeling} tired, I went to bed."],["having + pp",["one action before another","satu tindakan sebelum yang lain"],"{Having finished} the work, she left."],["pp",["passive meaning","makna pasif"],"{Built} in 1890, the house needs repairs."],["noun + -ing / pp",["reduced relative clause","klausa relatif yang dipendekkan"],"People {living} here… / Goods {made} in China…"]]}],"examples":[["Not knowing what to say, he stayed silent.","Karena tidak tahu harus berkata apa, dia diam."],["Having lived abroad, she speaks three languages.","Karena pernah tinggal di luar negeri, dia berbicara tiga bahasa."],["Asked about the plan, the minister refused to comment.","Ketika ditanya tentang rencana itu, menteri menolak berkomentar."]],"tip":["Avoid 'dangling' participles: 'Walking home, it started to rain' is wrong — the rain wasn't walking.","Hindari partisip 'menggantung': 'Walking home, it started to rain' salah — hujannya tidak berjalan."]},{"id":"c1-emphasis","title":["Emphasis: do/does/did, so, such, the very, ever","Penekanan: do/does/did, so, such, the very, ever"],"what":["Ways to add emphasis without changing the meaning: auxiliary 'do' in positive sentences, intensifiers and emphatic words.","Cara menambah penekanan tanpa mengubah arti: 'do' bantu dalam kalimat positif, penguat dan kata penekan."],"pattern":[{"head":[["Device","Cara"],["Example","Contoh"]],"rows":[["do / does / did + base","I {do like} it. She {did call}."],["the very","That's {the very} book I wanted."],["-ever (whoever, whatever…)","{Whatever} happens, stay calm."],["on earth / ever (in questions)","What {on earth} is that? Why {ever} did you go?"],["at all / whatsoever (negatives)","I have no idea {whatsoever}."],["by far","She's {by far} the best."]]}],"examples":[["I did tell you — you just forgot.","Saya sudah memberi tahu kamu — kamu saja yang lupa."],["Do sit down.","Silakan duduk."],["There's no doubt at all.","Sama sekali tidak ada keraguan."]],"tip":["Emphatic 'do' is stressed in speech: 'I DO understand'.","'Do' penekan diucapkan dengan tekanan: 'I DO understand'."]},{"id":"c1-hedging","title":["Hedging and cautious language","Bahasa berhati-hati (hedging)"],"what":["Soften claims to sound careful and academic: seem/appear, tend to, it is likely that, arguably, to some extent.","Melunakkan klaim agar terdengar hati-hati dan akademis: seem/appear, tend to, it is likely that, arguably, to some extent."],"pattern":[{"head":[["Direct","Langsung"],["Hedged","Berhati-hati"]],"rows":[["Prices are rising.","Prices {appear to be} rising."],["This causes stress.","This {may contribute to} stress."],["People prefer cities.","People {tend to} prefer cities."],["He will win.","{It is likely that} he will win. / He {is likely to} win."],["The plan failed.","The plan {was not entirely} successful."],["This is the best option.","This is {arguably} the best option."]]}],"examples":[["There seems to be a problem.","Sepertinya ada masalah."],["The results suggest that…","Hasilnya menunjukkan bahwa…"],["To some extent, I agree.","Sampai batas tertentu, saya setuju."]],"tip":["'Seem/appear' + to + base, or + to have + pp for the past: 'He seems to have left'.","'Seem/appear' + to + bentuk dasar, atau + to have + pp untuk masa lalu: 'He seems to have left'."]},{"id":"c1-ellipsis","title":["Ellipsis and substitution: so, not, do so, one","Elipsis dan substitusi: so, not, do so, one"],"what":["Avoid repetition by leaving words out or replacing them with so, not, one(s), do (so), or an auxiliary.","Menghindari pengulangan dengan menghilangkan kata atau menggantinya dengan so, not, one(s), do (so), atau kata kerja bantu."],"pattern":[{"head":[["Device","Cara"],["Example","Contoh"]],"rows":[["think / hope / expect + so","\"Is it ready?\" — \"I {think so}.\""],["hope / be afraid + not","\"Will it rain?\" — \"I {hope not}.\""],["one / ones","I prefer the red {one}."],["auxiliary only","She can swim, but I {can't}."],["to (infinitive)","I'd like to, but I don't {want to}."],["do so","Leave now, if you wish to {do so}."]]}],"examples":[["\"Are they coming?\" — \"I suppose so.\"","\"Mereka datang?\" — \"Kayaknya iya.\""],["\"Is he angry?\" — \"I'm afraid so.\"","\"Dia marah?\" — \"Sayangnya iya.\""],["I haven't finished, but I will.","Saya belum selesai, tapi nanti akan."]],"tip":["Negative: 'I hope not' / 'I don't think so' — not 'I don't hope so'.","Negatif: 'I hope not' / 'I don't think so' — bukan 'I don't hope so'."]},{"id":"c1-subjunctive","title":["The subjunctive and formal 'should'","Subjungtif dan 'should' formal"],"what":["After verbs and adjectives of demand or importance (suggest, insist, recommend, essential, vital), formal English uses the base form for every person.","Setelah kata kerja dan kata sifat tuntutan atau kepentingan (suggest, insist, recommend, essential, vital), bahasa Inggris formal memakai bentuk dasar untuk semua persona."],"pattern":[{"head":[["Trigger","Pemicu"],["Example","Contoh"]],"rows":[["suggest / recommend that","I suggest that he {see} a doctor."],["insist / demand that","They insisted that she {be} present."],["it is essential / vital that","It is vital that everyone {arrive} on time."],["negative","We ask that you {not smoke}."],["British alternative: should","I suggest that he {should see} a doctor."],["fixed phrases","{Be that as it may}… / {God save} the King."]]}],"examples":[["The doctor recommended that she rest.","Dokter menyarankan agar dia beristirahat."],["It's important that he be told.","Penting bahwa dia diberi tahu."]],"tip":["No -s and no past: 'that he see', 'that she be' — even in a past sentence.","Tanpa -s dan tanpa bentuk lampau: 'that he see', 'that she be' — bahkan dalam kalimat lampau."]},{"id":"c1-nominal","title":["Nominalisation (noun-based style)","Nominalisasi (gaya berbasis kata benda)"],"what":["Formal writing turns verbs and adjectives into nouns, making the text more compact and impersonal.","Tulisan formal mengubah kata kerja dan kata sifat menjadi kata benda, sehingga teks lebih ringkas dan impersonal."],"pattern":[{"head":[["Verb-based","Berbasis kata kerja"],["Noun-based","Berbasis kata benda"]],"rows":[["Prices increased sharply.","There was a sharp {increase} in prices."],["They decided to close the factory.","The {decision} to close the factory…"],["Because it rained heavily…","Due to {heavy rainfall}…"],["When the company failed…","The {failure} of the company…"],["Unemployment is rising, which worries us.","The {rise in} unemployment is a concern."]]}],"examples":[["The introduction of the new rules caused confusion.","Diberlakukannya aturan baru menimbulkan kebingungan."],["Her refusal to cooperate delayed the project.","Penolakannya untuk bekerja sama menunda proyek."]],"tip":["Common endings: -tion, -ment, -ance/-ence, -ity, -al, -ure (arrive → arrival, fail → failure).","Akhiran umum: -tion, -ment, -ance/-ence, -ity, -al, -ure (arrive → arrival, fail → failure)."]},{"id":"c1-discourse","title":["Discourse markers for argument","Penanda wacana untuk argumen"],"what":["Words that organise a text: adding, contrasting, conceding, concluding and giving examples.","Kata-kata yang mengatur teks: menambah, mengontraskan, mengakui, menyimpulkan dan memberi contoh."],"pattern":[{"head":[["Function","Fungsi"],["Markers","Penanda"]],"rows":[[["adding","menambah"],"{moreover, furthermore, in addition, what is more}"],[["contrast","kontras"],"{nevertheless, nonetheless, on the other hand, conversely}"],[["concession","pengakuan"],"{admittedly, granted, while it is true that}"],[["result","akibat"],"{consequently, therefore, as a result, thus}"],[["example","contoh"],"{for instance, such as, notably}"],[["conclusion","kesimpulan"],"{in conclusion, all in all, on balance}"]]}],"examples":[["Admittedly, the plan is costly. Nevertheless, it is necessary.","Memang rencananya mahal. Meskipun demikian, rencana itu perlu."],["On balance, the benefits outweigh the costs.","Secara keseluruhan, manfaatnya lebih besar daripada biayanya."]],"tip":["'On the other hand' introduces the other side; 'on the contrary' rejects what was just said.","'On the other hand' memperkenalkan sisi lain; 'on the contrary' membantah yang baru dikatakan."]},{"id":"c1-modals-adv","title":["Advanced modals: be bound to, be supposed to, would rather, had better","Modal lanjutan: be bound to, be supposed to, would rather, had better"],"what":["Semi-modal expressions for certainty, expectation, preference and advice.","Ungkapan semi-modal untuk kepastian, harapan, preferensi dan saran."],"pattern":[{"head":[["Expression","Ungkapan"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["be bound to",["certain to","pasti akan"],"It's {bound to} rain."],["be supposed to",["expected / arranged","seharusnya (menurut aturan/rencana)"],"You're {supposed to} wear a helmet."],["be (un)likely to",["probable","kemungkinan"],"He's {unlikely to} come."],["would rather + base / + past",["prefer","lebih suka"],"I'd {rather stay}. / I'd rather you {stayed}."],["had better + base",["strong advice","sebaiknya (peringatan)"],"You'd {better hurry}."],["be to + base",["formal plan / order","rencana / perintah formal"],"The president {is to visit} Prague."]]}],"examples":[["We were supposed to meet at six.","Seharusnya kita bertemu jam enam."],["I'd rather not talk about it.","Saya lebih suka tidak membicarakannya."],["You'd better not be late.","Sebaiknya kamu jangan terlambat."]],"tip":["'Had better' + base form (no 'to'): 'You'd better go', not 'You'd better to go'.","'Had better' + bentuk dasar (tanpa 'to'): 'You'd better go', bukan 'You'd better to go'."]},{"id":"c1-unreal-past","title":["Unreal past: it's time, as if, suppose, would rather","Masa lalu tidak nyata: it's time, as if, suppose, would rather"],"what":["After certain expressions, a past form refers to the present or future to show it is unreal or not yet true.","Setelah ungkapan tertentu, bentuk lampau merujuk ke sekarang atau masa depan untuk menunjukkan hal itu tidak nyata atau belum terjadi."],"pattern":[{"head":[["Expression","Ungkapan"],["Example","Contoh"]],"rows":[["It's (high/about) time + past","It's time we {went} home."],["as if / as though + past","He talks as if he {knew} everything."],["as if + past perfect","She looked as if she {had seen} a ghost."],["suppose / supposing + past","Suppose you {lost} your job — what then?"],["would rather + someone + past","I'd rather you {didn't tell} anyone."],["if only + past","If only I {were} taller."]]}],"examples":[["It's high time you found a job.","Sudah saatnya kamu mencari pekerjaan."],["Don't treat me as if I were a child.","Jangan perlakukan saya seolah-olah saya anak kecil."]],"tip":["Formal English prefers 'were' for all persons: 'as if I were', 'if only she were'.","Bahasa Inggris formal memakai 'were' untuk semua persona: 'as if I were', 'if only she were'."]},{"id":"c1-dependent-prep","title":["Dependent prepositions","Preposisi yang melekat"],"what":["Many verbs, adjectives and nouns take a fixed preposition. They must be learnt as a unit.","Banyak kata kerja, kata sifat dan kata benda memakai preposisi tetap. Harus dipelajari sebagai satu kesatuan."],"pattern":[{"head":[["Word + prep","Kata + prep"],["Example","Contoh"]],"rows":[["depend {on}","It depends on the weather."],["insist {on} + -ing","He insisted on paying."],["accuse sb {of}","They accused him of lying."],["be aware {of}","Are you aware of the risks?"],["be responsible {for}","Who is responsible for this?"],["object {to} + -ing","I object to working weekends."],["a reason {for}","There's no reason for concern."],["an increase {in}","an increase in prices"],["be capable {of}","She's capable of anything."],["succeed {in} + -ing","We succeeded in finishing."]]}],"examples":[["I'm not interested in politics.","Saya tidak tertarik pada politik."],["She apologised for the delay.","Dia meminta maaf atas keterlambatan."],["He was accused of fraud.","Dia dituduh melakukan penipuan."]],"tip":["After a preposition, use -ing: 'I look forward to seeing you' ('to' is a preposition here).","Setelah preposisi, pakai -ing: 'I look forward to seeing you' ('to' di sini adalah preposisi)."]}]},{"id":"C2","name":["Proficiency","Sangat mahir"],"goal":["Control style and nuance like an educated native speaker: fronting, formal conditionals, register, idioms, word formation and dense noun phrases.","Menguasai gaya dan nuansa seperti penutur asli terpelajar: pengedepanan, pengandaian formal, register, idiom, pembentukan kata dan frasa nomina padat."],"topics":[{"id":"c2-fronting","title":["Fronting and inversion after place/so/such","Pengedepanan dan inversi setelah tempat/so/such"],"what":["Moving a part of the sentence to the front for emphasis or style. After place adverbials and 'so/such … that' at the start, the verb often comes before the subject.","Memindahkan bagian kalimat ke depan untuk penekanan atau gaya. Setelah keterangan tempat dan 'so/such … that' di awal, kata kerja sering mendahului subjek."],"pattern":[{"head":[["Type","Jenis"],["Example","Contoh"]],"rows":[[["object fronting","objek di depan"],"{That} I can't accept."],[["adjective + as/though","kata sifat + as/though"],"{Tired as she was}, she kept going."],[["place + verb + subject","tempat + kata kerja + subjek"],"{On the hill stood} an old castle."],[["so + adj + inversion","so + sifat + inversi"],"{So strong was} the wind that trees fell."],[["such + be + inversion","such + be + inversi"],"{Such was} his anger that he left."],[["here/there + verb","here/there + kata kerja"],"{Here comes} the bus. (but: Here it comes.)"]]}],"examples":[["Into the room walked a tall stranger.","Masuklah ke ruangan itu seorang asing yang tinggi."],["Strange though it may seem, it's true.","Meskipun tampak aneh, itu benar."],["So little did he care that he didn't even call.","Dia begitu tidak peduli sampai-sampai tidak menelepon."]],"tip":["With a pronoun subject there is no inversion after place: 'Here it comes', 'Off they went'.","Bila subjeknya kata ganti, tidak ada inversi setelah tempat: 'Here it comes', 'Off they went'."]},{"id":"c2-inversion-cond","title":["Inverted conditionals: Had I known, Should you…, Were it not for","Pengandaian terbalik: Had I known, Should you…, Were it not for"],"what":["Formal conditionals drop 'if' and invert the auxiliary: Had (3rd), Were (2nd), Should (1st, unlikely).","Pengandaian formal menghilangkan 'if' dan membalik kata kerja bantu: Had (tipe 3), Were (tipe 2), Should (tipe 1, kecil kemungkinan)."],"pattern":[{"head":[["Normal","Biasa"],["Inverted","Terbalik"]],"rows":[["If I had known, …","{Had I known}, I would have helped."],["If I were you, …","{Were I you}, I'd accept."],["If you should need help, …","{Should you need} help, call us."],["If it were not for her, …","{Were it not for} her, we'd be lost."],["If it had not been for the rain, …","{Had it not been for} the rain, we'd have won."],["If they were to refuse, …","{Were they to refuse}, we'd cancel."]]}],"examples":[["Should you have any questions, please contact us.","Bila ada pertanyaan, silakan hubungi kami."],["Had it not been for your help, I'd have failed.","Seandainya bukan karena bantuanmu, saya pasti gagal."]],"tip":["Negatives are not contracted: 'Had I not known', never 'Hadn't I known'.","Bentuk negatif tidak disingkat: 'Had I not known', bukan 'Hadn't I known'."]},{"id":"c2-register","title":["Register: formal vs informal","Register: formal vs informal"],"what":["Choosing words and structures to fit the situation: Latin-based verbs and passives in formal texts, phrasal verbs and contractions in informal speech.","Memilih kata dan struktur sesuai situasi: kata kerja asal Latin dan pasif dalam teks formal, kata kerja frasal dan singkatan dalam percakapan informal."],"pattern":[{"head":[["Informal","Informal"],["Formal","Formal"]],"rows":[["find out","{ascertain} / discover"],["put off","{postpone}"],["get in touch","{contact}"],["ask for","{request}"],["help","{assist}"],["need","{require}"],["Sorry, but…","{We regret to inform you that}…"],["Can you…?","{I would be grateful if you could}…"]]}],"examples":[["Please find attached the requested documents.","Terlampir dokumen yang diminta."],["Hey, just checking in — got a sec?","Hai, cuma mau tanya — ada waktu sebentar?"],["Your cooperation is greatly appreciated.","Kerja sama Anda sangat kami hargai."]],"tip":["Mixing registers sounds odd: don't write 'We regret to inform you that the meeting is kinda off'.","Mencampur register terdengar aneh: jangan tulis 'We regret to inform you that the meeting is kinda off'."]},{"id":"c2-idioms","title":["Idioms and fixed expressions","Idiom dan ungkapan tetap"],"what":["Expressions whose meaning is not the sum of their words. Their form is fixed: words can't be swapped.","Ungkapan yang artinya bukan gabungan arti kata-katanya. Bentuknya tetap: kata-katanya tidak bisa ditukar."],"pattern":[{"head":[["Idiom","Idiom"],["Meaning","Arti"]],"rows":[["{a blessing in disguise}",["something good that first looked bad","hikmah di balik musibah"]],["{the last straw}",["the final problem that makes you give up","batas kesabaran"]],["{beat around the bush}",["avoid saying something directly","berbelit-belit"]],["{cut corners}",["do something badly to save time/money","mengambil jalan pintas (asal-asalan)"]],["{once in a blue moon}",["very rarely","sangat jarang"]],["{get the hang of}",["learn how to do","mulai menguasai"]],["{by and large}",["in general","secara umum"]],["{on the fence}",["undecided","belum memutuskan"]]]}],"examples":[["Losing that job was a blessing in disguise.","Kehilangan pekerjaan itu ternyata ada hikmahnya."],["Stop beating around the bush and tell me.","Jangan berbelit-belit, katakan saja."],["I'm still on the fence about moving.","Saya masih belum memutuskan soal pindah."]],"tip":["Fixed means fixed: 'beat around the bush', not 'hit around the tree'.","Tetap berarti tetap: 'beat around the bush', bukan 'hit around the tree'."]},{"id":"c2-distancing","title":["Distancing and tentative language","Bahasa menjaga jarak dan tentatif"],"what":["Past forms and continuous forms make requests and opinions softer and more polite; impersonal structures distance the speaker from a claim.","Bentuk lampau dan continuous membuat permintaan dan pendapat lebih lunak dan sopan; struktur impersonal menjaga jarak pembicara dari klaim."],"pattern":[{"head":[["Direct","Langsung"],["Distanced","Berjarak"]],"rows":[["I want to ask you…","I {was wondering if} I could ask you…"],["I hope you can help.","I {was hoping} you could help."],["Do you want…?","{Would} you {like}…?"],["You're wrong.","{I'm not sure} that's {quite} right."],["It's a bad idea.","It {might not be} the best idea."],["They say he lied.","He {is alleged to have} lied."]]}],"examples":[["I was thinking we could meet next week.","Saya terpikir kita bisa bertemu minggu depan."],["There would appear to be a mistake.","Tampaknya ada kesalahan."],["The minister is reported to be resigning.","Menteri itu dikabarkan akan mengundurkan diri."]],"tip":["'I was wondering' is about now, not the past — the past form is only for politeness.","'I was wondering' tentang sekarang, bukan masa lalu — bentuk lampau hanya untuk kesopanan."]},{"id":"c2-spelling","title":["Tricky spelling and commonly confused words","Ejaan sulit dan kata yang sering tertukar"],"what":["Pairs that sound alike or look alike but differ in meaning and spelling.","Pasangan kata yang bunyinya atau tampilannya mirip tetapi arti dan ejaannya berbeda."],"pattern":[{"head":[["Pair","Pasangan"],["Example","Contoh"]],"rows":[["affect (v) / effect (n)","It {affects} us. The {effect} was huge."],["its / it's","The dog wagged {its} tail. {It's} late."],["principle / principal","a matter of {principle} / the school {principal}"],["complement / compliment","Wine {complements} food. He paid me a {compliment}."],["stationary / stationery","a {stationary} car / office {stationery}"],["lose / loose","Don't {lose} it. The screw is {loose}."],["practice (n) / practise (v, UK)","I need more {practice}. I {practise} daily."],["accommodation, necessary, separate","double c, double m; one c, double s; sep-a-rate"]]}],"examples":[["Their house is over there, and they're at home.","Rumah mereka di sana, dan mereka ada di rumah."],["Whose bag is this? Who's coming?","Tas siapa ini? Siapa yang datang?"]],"tip":["'It's' always means 'it is' or 'it has'; the possessive 'its' has no apostrophe.","'It's' selalu berarti 'it is' atau 'it has'; posesif 'its' tanpa apostrof."]},{"id":"c2-word-formation","title":["Word formation: prefixes and suffixes","Pembentukan kata: awalan dan akhiran"],"what":["Build new words from a root: prefixes change meaning (un-, mis-, over-), suffixes change word class (-ness, -ise, -ive, -ly).","Membentuk kata baru dari akar: awalan mengubah arti (un-, mis-, over-), akhiran mengubah kelas kata (-ness, -ise, -ive, -ly)."],"pattern":[{"head":[["Affix","Imbuhan"],["Meaning / class","Arti / kelas"],["Example","Contoh"]],"rows":[["un- / in- / im- / ir- / il-",["not","tidak"],"unlikely, inefficient, impossible, irregular, illegal"],["mis-",["wrongly","salah"],"misunderstand, mislead"],["over- / under-",["too much / too little","terlalu banyak / sedikit"],"overestimate, underpaid"],["-ness / -ity / -ment",["noun","kata benda"],"kindness, ability, agreement"],["-ise (-ize) / -en / -ify",["verb","kata kerja"],"modernise, widen, simplify"],["-ive / -ous / -able / -ful",["adjective","kata sifat"],"creative, dangerous, reliable, helpful"]]}],"examples":[["The instructions were misleading.","Petunjuknya menyesatkan."],["Her reliability is unquestionable.","Keandalannya tidak diragukan."],["They widened the road.","Mereka melebarkan jalannya."]],"tip":["im- before b/m/p (impossible), il- before l (illegal), ir- before r (irrelevant).","im- sebelum b/m/p (impossible), il- sebelum l (illegal), ir- sebelum r (irrelevant)."]},{"id":"c2-noun-phrases","title":["Complex noun phrases","Frasa nomina kompleks"],"what":["Academic English packs information into long noun phrases with pre-modifiers (adjectives, nouns) and post-modifiers (prepositional phrases, participles, relative clauses).","Bahasa Inggris akademis memadatkan informasi dalam frasa nomina panjang dengan pewatas depan (kata sifat, kata benda) dan pewatas belakang (frasa preposisi, partisip, klausa relatif)."],"pattern":[{"head":[["Part","Bagian"],["Example","Contoh"]],"rows":[[["pre-modifier: adjective + noun","pewatas depan: sifat + benda"],"a {rapid population} increase"],[["compound noun","kata benda majemuk"],"a {government education} policy"],[["post-modifier: preposition phrase","pewatas belakang: frasa preposisi"],"the impact {of climate change on farming}"],[["post-modifier: participle","pewatas belakang: partisip"],"the measures {taken by the government}"],[["post-modifier: to-infinitive","pewatas belakang: to-infinitif"],"the decision {to raise taxes}"],[["all together","semuanya"],"the {recent sharp} rise {in energy prices caused by the war}"]]}],"examples":[["A ten-year-old boy won the prize.","Seorang anak laki-laki berumur sepuluh tahun memenangkan hadiah."],["The number of students applying has doubled.","Jumlah mahasiswa yang mendaftar meningkat dua kali lipat."]],"tip":["Noun modifiers are singular: 'a ten-year-old boy', 'a three-hour flight' (not 'years', 'hours').","Kata benda pewatas berbentuk tunggal: 'a ten-year-old boy', 'a three-hour flight' (bukan 'years', 'hours')."]}]}]};
